COLLDATA("tadabburar","ar",[[428,"§سبإ\nwords\nيَلِجُيَدخُلُ.\nيَعرُجُيَصعَدُ.\nلاَ يَعزُبُلاَ يَغِيبُ.\nعَذَابٌ مِن رِجزٍ أَلِيمٌأَسوَأُ العَذَابِ، وَأَشَدُّهُ أَلَمًا.\nمُزِّقتُممُتُّم، وَتَفَرَّقَت أَجسَادُكُم فِي الأَرضِ.\ndeeds\nقل: \"اللهم جازني بالحسنات إحسانًا، وبالسيئات عفوًا وغفرانًا\".\nاعمل عملًا صالحًا جديدًا اليوم؛ رجاء أن يغفر الله لك، ويرزقك رزقًا كريمًا.\nاحضر درسًا علميًا؛ رجاء معرفة الحق من الباطل.\nguid\nمن أكثر من حمد الله في الدنيا حري أن يكون ممن يحمده في الآخرة.\nكن ممن يدعو إلي دين الله تعالى وينافح عنه، و احذر من أن تكون ممن يسعى في الصد عنه.\nالعلم الشرعي الصحيح المبني على اتباع كلام الله وسنة نبيه يوصل إلى فلاح الدنيا والآخرة.\nrefl\nٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ\nافتتحت السورة ب﴿ٱلۡحَمۡدُ لِلَّهِ﴾ للتنبيه على أن السورة تتضمن من دلائل تفرده بالإِلهية واتصافه بصفات العظمة ما يقتضي إنشاء الحمد له، والإِخبار باختصاصه به. ابن عاشور:٢٢/١٣٥.\nما مناسبة افتتاح سورة سبأ ب﴿ٱلۡحَمۡدُ لِلَّهِ﴾؟\nٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ\nوفي هذه الصلة تعريض بكفران المشركين؛ الذين حمدوا أشياء ليس لها في هذه العوالم أدنى تأثير، ولا لها بما تحتوي عليه أدنى شعور، ونَسُوا حمد مالكها وسائر ما في السماوات والأرض. ابن عاشور:٢٢/١٣٦.\nما فائدة صلة الموصول في الآية الكريمة؟\nوَلَهُ ٱلۡحَمۡدُ فِي ٱلۡأٓخِرَةِۚ\nلأن في الآخرة يظهر من حمده والثناء عليه ما لا يكون في الدنيا؛ فإذا قضى الله تعالى بين الخلائق كلهم، ورأى الناس والخلق كلهم ما حكم به، وكمال عدله وقسطه وحكمته فيه، حمدوه كلهم على ذلك، حتى أهل العقاب ما دخلوا النار إلا وقلوبهم ممتلئة من حمده، وأن هذا من جرّاء أعمالهم، وأنه عادل في حكمه بعقابهم. السعدي:٦٧٤.\nلماذا خص حمده في الآخرة؟\nعَٰلِمِ ٱلۡغَيۡبِۖ لَا يَعۡزُبُ عَنۡهُ مِثۡقَالُ ذَرَّةٖ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِ وَلَآ أَصۡغَرُ مِن ذَٰلِكَ وَلَآ أَكۡبَرُ إِلَّا فِي كِتَٰبٖ مُّبِينٖ ٣\n﴿لَا يَعۡزُبُ عَنۡهُ﴾: لا يغيب عنه؛ أي: الجميع مندرج تحت علمه، فلا يخفى عليه شيء؛ فالعظام وإن تلاشت وتفرقت وتمزقت فهو عالم أين ذهبت وأين تفرقت، ثم يعيدها كما بدأها أول مرة؛ فإنه بكل شيء عليم. ابن كثير:٣/٥٠٤.\nلماذا خص وصف الله سبحانه بأنه ﴿أَعۡلَمُ ٱلۡغَيۡبَ﴾ بعد ذكر البعث؟\nوَيَرَى ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ ٱلَّذِيٓ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ هُوَ ٱلۡحَقَّ\nواختير فعل الرؤية هنا دون (ويعلم) للتنبيه على أنه علم يقيني بمنزلة العلم بالمرئيات التي علمها ضروري. ابن عاشور:٢٢/١٤٥.\nلماذا عبر بالفعل (ويرى) دون (يعلم) في الآية الكريمة؟\nوَيَرَى ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ ٱلَّذِيٓ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ هُوَ ٱلۡحَقَّ وَيَهۡدِيٓ إِلَىٰ صِرَٰطِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ ٦\nوإيثار وصفي ﴿ٱلۡعَزِيزِ ٱلۡحَمِيدِ﴾ هنا دون بقية الأسماء الحسنى إيماء إلى أن المؤمنين حين يؤمنون بأن القرآن هو الحق والهداية استشعروا من الإِيمان أنه صراط يُبلَغ به إلى العزة؛ قال تعالى: ﴿لِلَّهِ ٱلۡعِزَّةُ وَلِرَسُولِهِۦ وَلِلۡمُؤۡمِنِينَ﴾ [المنافقون:٨]. ابن عاشور:٢٢/١٤٦.\nما فائدة إيثار وصفي ﴿ٱلۡعَزِيزِ ٱلۡحَمِيدِ﴾ في الآية الكريمة؟\nوَقَالَ ٱلَّذِينَ كَفَرُواْ هَلۡ نَدُلُّكُمۡ عَلَىٰ رَجُلٖ يُنَبِّئُكُمۡ إِذَا مُزِّقۡتُمۡ كُلَّ مُمَزَّقٍ إِنَّكُمۡ لَفِي خَلۡقٖ جَدِيدٍ ٧\nفإن قلت: كان رسول الله -صلى الله عليه وسلم- مشهورًا علمًا في قريش، وكان إنباؤه بالبعث شائعًا عندهم، فما معنى قولهم: ﴿هَلۡ نَدُلُّكُمۡ عَلَىٰ رَجُلٍ﴾ فنكّروه لهم، وعرضوا عليهم الدلالة عليه كما يدل على مجهول في أمر مجهول؟ قلت: كانوا يقصدون بذلك... الهزء والسخرية... للضحك والتلهي متجاهلين به وبأمره. القرطبي:١٧/٢٥٧.\nلم تجاهلوا أمر النبي -صلى الله عليه وسلم- بوصفهم إياه بــ(رجل)؟"],[429,"§سبإ\nwords\nكِسَفًاقِطَعًا مِنَ العَذَابِ.\nمُنِيبٍرَاجِعٍ إِلَى رَبِّهِ بِالتَّوبَةِ وَالطَّاعَةِ.\nأَوِّبِي مَعَهُسَبِّحِي مَعَهُ.\nوَقَدِّر فِي السَّردِقَدِّرِ المَسَامِيرَ فِي حِلَقِ الدُّرُوعِ بِأَلاَّ تَكُونَ الحِلَقُ صَغِيرَةً ضَعِيفَةً، وَلاَ كَبِيرَةً ثَقِيلَةً.\nعَينَ القِطرِعَينَ النُّحَاسِ، فَيَسِيلُ لَهُ النُّحَاسُ كَالمَاءِ.\nوَجِفَانٍ كَالجَوَابِقِصَاعٍ كَبِيرَةٍ؛ كَالأَحوَاضِ الَّتِي يَجتَمِعُ فِيهَا المَاءُ.\ndeeds\nأتقن جميع أعمالك هذا اليوم على الوجه الذي يرضي الله سبحانه.\nعلّم مسلمًا سورة من سور القرآن؛ شكرًا لله على حفظك للسورة.\nقل: \"اللهم اجعلني من عبادك الشاكرين\".\nguid\nكثرة الإنابة إلى الله سببٌ للانتفاع بالآيات الكونية.\nليكن لك صنعة تحسنها أو مهارة تتقنها، تستعف بها عن الناس.\nالغيب لا يعلمه إلا الله تعالى.\nrefl\nأَفَلَمۡ يَرَوۡاْ إِلَىٰ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ إِن نَّشَأۡ نَخۡسِفۡ بِهِمُ ٱلۡأَرۡضَ أَوۡ نُسۡقِطۡ عَلَيۡهِمۡ كِسَفٗا مِّنَ ٱلسَّمَآءِۚ\nأعلم الله تعالى أن الذي قدر على خلق السماوات والأرض وما فيهن؛ قادر على البعث، وعلى تعجيل العقوبة لهم؛ فاستدل بقدرته عليهم، وأن السماوات والأرض ملكه، وأنهما محيطتان بهم من كل جانب؛ فكيف يأمنون الخسف والكسف، كما فعل بقارون وأصحاب الأيكة. القرطبي:١٧/٢٥٩.\nما دلالة قدرة الله -سبحانه وتعالى- في خلق السموات والأرض على قدرته على عقوبة العصاة؟\nإِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّكُلِّ عَبۡدٖ مُّنِيبٖ ٩\nفكلما كان العبد أعظم إنابة إلى الله كان انتفاعه بالآيات أعظم؛ لأن المنيب مقبل إلى ربه، قد توجهت إراداته وهماته لربه، ورجع إليه في كل أمر من أموره، فصار قريبًا من ربه، ليس له هم إلا الاشتغال بمرضاته؛ فيكون نظره للمخلوقات نظر فكرة وعبرة، لا نظر غفلة غير نافعة. السعدي:٦٧٦.\nلماذا اختص الانتفاع بالآيات بالعباد المنيبين إلى الله -سبحانه وتعالى-؟\n۞وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ مِنَّا فَضۡلٗاۖ يَٰجِبَالُ أَوِّبِي مَعَهُۥ وَٱلطَّيۡرَۖ وَأَلَنَّا لَهُ ٱلۡحَدِيدَ ١٠\nوتنكير (فضلًا) لتعظيمه؛ وهو فضل النبوءة، وفضل المُلك، وفضل العناية بإصلاح الأمة، وفضل القضاء بالعدل، وفضل الشجاعة في الحرب، وفضل سَعَة النعمة عليه، وفضل إغنائه عن الناس بما ألهمه من صنع دروع الحديد، وفضل إيتائه الزبور، وإيتائه حسن الصوت، وطولَ العمر في الصلاح، وغير ذلك. ابن عاشور:٢٢/١٥٥.\nما فائدة تنكير (فضلًا) في الآية الكريمة؟\nأَنِ ٱعۡمَلۡ سَٰبِغَٰتٖ وَقَدِّرۡ فِي ٱلسَّرۡدِۖ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ بَصِيرٞ ١١\nفي هذه الآية دليل على تعلم أهل الفضل الصنائع، وأن التحرُّف بها لا ينقص من مناصبهم، بل ذلك زيادة في فضلهم وفضائلهم؛ إذ يحصل لهم التواضع في أنفسهم، والاستغناء عن غيرهم، وكسب الحلال الخلي عن الامتنان. القرطبي:١٧/٢٦٣.\nهل في تعلم طالب العلم للصنائع والمهارات منقصة؟\nٱعۡمَلُوٓاْ ءَالَ دَاوُۥدَ شُكۡرٗاۚ\nفيه دلالة على أن الشكر يكون بالفعل كما يكون بالقول والنية؛ كما قال الشاعر: أفادتكم النعماء مني ثلاثة * يدي ولساني والضمير المحجبا. ابن كثير:٣/٥٠٧.\nما طرائق الشكر التي يشكر بها الإنسانُ ربَّه؟\nٱعۡمَلُوٓاْ ءَالَ دَاوُۥدَ شُكۡرٗاۚ وَقَلِيلٞ مِّنۡ عِبَادِيَ ٱلشَّكُورُ ١٣\nروي أن داود -عليه السلام- قال: يارب، كيف أطيق شكرك على نعمك، وإلهامي وقدرتي على شكرك نعمة لك؟ فقال: ياداود الآن عرفتني... والشكر حقيقته: الاعتراف بالنعمة للمنعم، واستعمالها في طاعته، والكفران: استعمالها في المعصية؛ وقليل من يفعل ذلك. القرطبي:١٧/٢٧٨.\nبيّن كيف تكون حقيقة الشكر، وهل أهل الشكر كثير؟\nفَلَمَّا قَضَيۡنَا عَلَيۡهِ ٱلۡمَوۡتَ مَا دَلَّهُمۡ عَلَىٰ مَوۡتِهِۦٓ إِلَّا دَآبَّةُ ٱلۡأَرۡضِ تَأۡكُلُ مِنسَأَتَهُۥۖ فَلَمَّا خَرَّ تَبَيَّنَتِ ٱلۡجِنُّ أَن لَّوۡ كَانُواْ يَعۡلَمُونَ ٱلۡغَيۡبَ مَا لَبِثُواْ فِي ٱلۡعَذَابِ ٱلۡمُهِينِ ١٤\nوالمعنى: ظهر للناس أن الجن لا يعلمون الغيب، وقيل: تبينت بمعنى علمت. ابن جزي:٢/٢٠٣.\nكيف ترد على من يزعم أن الجن يعلمون الغيب؟"],[430,"§سبإ\nwords\nآيَةٌدَلاَلَةٌ عَلَى قُدرَتِنَا.\nذَوَاتَيصَاحِبَتَي.\nسَيلَ العَرِمِالسَّيلَ الجَارِفَ الشَّدِيدَ الَّذِي خَرَّبَ السَّدَّ، وَأَغرَقَ البَسَاتِينَ.\nأُكُلٍ خَمطٍثَمَرٍ مُرٍّ، كَرِيهِ الطَّعمِ.\nوَأَثلٍشَجَرٍ مَعرُوفٍ شَبِيهٍ بِالطَّرفَاءِ، لاَ ثَمَرَ لَهُ.\nسِدرٍشَجَرِ النَّبَقِ، كَثِيرِ الشَّوكِ.\ndeeds\nسمّ الله قبل الأكل، واحمده بعده؛ شكرًا لله تعالى.\nعدد ثـلاث عواقب من عواقب كفر النعم من خلال آيـات قـصة سـبأ.\nارسل رسالة لأقاربك وزملائك تذكّرهم بالعقوبات الإلهية لمن أعرض عن دين الله.\nguid\nاحذر من كفر نعم الله تعالى.\nادعُ بما ينفعك واحذر من الدعاء بما يضرك.\nاحذر وساوس الشيطان ونزغاته.\nrefl\nلَقَدۡ كَانَ لِسَبَإٖ فِي مَسۡكَنِهِمۡ ءَايَةٞۖ\nجرَّ خبرُ سليمان -عليه السلام- إلى ذكر سبأ لما بين مُلك سليمان وبين مملكة سبأ من الاتصال بسبب قصة (بلقيس)، ولأن في حال أهل سبأ مضادة لأحوال داود وسليمان؛ إذ كان هذان مثلًا في إسباغ النعمة على الشاكرين، وكان أولئك مثلًا لسلب النعمة عن الكافرين. ابن عاشور:٢٢/١٦٥.\nاذكر مناسبات مجيء قصة سبأ بعد قصة سليمان -عليه السلام-.\nفَأَعۡرَضُواْ فَأَرۡسَلۡنَا عَلَيۡهِمۡ سَيۡلَ ٱلۡعَرِمِ وَبَدَّلۡنَٰهُم بِجَنَّتَيۡهِمۡ جَنَّتَيۡنِ ذَوَاتَيۡ أُكُلٍ خَمۡطٖ وَأَثۡلٖ وَشَيۡءٖ مِّن سِدۡرٖ قَلِيلٖ ١٦\n(فَأَعرَضُوا) أي: أعرضوا عن شكر الله، أو عن طاعة الأنبياء. ابن جزي:٢/٢٠٣.\nما الأمر الذي أعرض عنه أهل سبأ وبسببه تبدَّل حالهم؟\nوَبَدَّلۡنَٰهُم بِجَنَّتَيۡهِمۡ جَنَّتَيۡنِ ذَوَاتَيۡ أُكُلٍ خَمۡطٖ وَأَثۡلٖ وَشَيۡءٖ مِّن سِدۡرٖ قَلِيلٖ ١٦\nوهذا من جنس عملهم؛ فكما بدلوا الشكر الحسن بالكفر القبيح، بدلوا تلك النعمة بما ذكر.السعدي:٦٧٧.\nتكلم عن قاعدة \"الجزاء من جنس العمل\" من خلال الآية الكريمة.\nوَجَعَلۡنَا بَيۡنَهُمۡ وَبَيۡنَ ٱلۡقُرَى ٱلَّتِي بَٰرَكۡنَا فِيهَا قُرٗى ظَٰهِرَةٗ وَقَدَّرۡنَا فِيهَا ٱلسَّيۡرَۖ سِيرُواْ فِيهَا لَيَالِيَ وَأَيَّامًا ءَامِنِينَ ١٨\nوقوله تعالى: ﴿وَقَدَّرۡنَا فِيهَا ٱلسَّيۡرَۖ﴾ هو ما ذكرناه من أن المسافر فيها كان يبيت في قرية ويقيل في أخرى على أي طريق سلك؛ لا يعوزه ذلك. وقوله تعالى: (سِيرُوا) معناه: قلنا لهم. و(آمِنِينَ) معناه: من الخوف من الناس المفسدين، وآمِنِينَ من الجوع والعطش وآفات المسافر. ابن عطية:٤/٤١٦.\nما معنى كل من: ﴿وَقَدَّرۡنَا فِيهَا ٱلسَّيۡرَۖ﴾ و(آمِنِينَ) الواردين في الآية ؟\nإِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ ١٩\nوجُمع (الآيات) لأن في تلك القصة عدة آيات وعِبَر؛ فحالةُ مساكنهم آية على قدرة الله ورحمته وإنعامه... وفي إرسال سيل العرم عَليهم آية على انفراده تعالى بالتصرف، وعلى أنه المنتقم... وفي انعكاس حالهم من الرفاهة إلى الشظف آية على تقلب الأحوال وتغير العالم... وفي ذلك آية من عدم الاطمئنان لدوام حال في الخير والشر، وفيما كان من عمران إقليمهم واتساع قراهم إلى بلاد الشام آية على مبلغ العمران وعظم السلطان من آيات التصرفات، وآية على أن الأمن أساس العمران، وفي تمنيهم زوال ذلك آية على ما قد تبلغه العقول من الانحطاط المفضي إلى اختلال أمور الأمة وذهاب عظمتها، وفيما صاروا إليه من النزوحِ عن الأوطان والتشتت في الأرض آية على ما يُلجئ الاضطرارُ إليه الناس من ارتكاب الأخطار والمكاره... والجمع بين (صبار) و(شكور) في الوصف لإِفادة أن واجب المؤمن التخلق بالخُلقين وهما: الصبر على المكاره، والشكر على النعم؛ وهؤلاء المتحدَّث عنهم لم يشكروا النعمة فبطروها، ولم يصبروا على ما أصابهم من زوالها. ابن عاشور:٢٢/١٨٠.\nلماذا جمعت كلمة (الآيات) في الآية؟ ولماذا جمع في آخرها بين (صبار) و(شكور)؟\nوَلَقَدۡ صَدَّقَ عَلَيۡهِمۡ إِبۡلِيسُ ظَنَّهُۥ فَٱتَّبَعُوهُ إِلَّا فَرِيقٗا مِّنَ ٱلۡمُؤۡمِنِينَ ٢٠\nقال ابن قتيبة: \"إن إبليس لمَّا سأل النظرة فأنظره الله، قال: لأغوينهم ولأضلنهم، لم يكن مستيقنًا وقت هذه المقالة أن ما قاله فيهم يتم، وإنَّما قاله ظنًّا، فلمّا اتبعوه وأطاعوه صدق عليهم ما ظنه فيهم\". قال الحسن: \"لم يسل عليهم سيفًا ولا ضربهم بسوط، وإنَّما وعدهم ومنَّاهم؛ فاغتروا\". البغوي:٣/٦٠٤.\nبيّن كيف صدق عليهم إبليس ظنه.\nوَمَا كَانَ لَهُۥ عَلَيۡهِم مِّن سُلۡطَٰنٍ إِلَّا لِنَعۡلَمَ مَن يُؤۡمِنُ بِٱلۡأٓخِرَةِ مِمَّنۡ هُوَ مِنۡهَا فِي شَكّٖۗ وَرَبُّكَ عَلَىٰ كُلِّ شَيۡءٍ حَفِيظٞ ٢١\nلم يقهرهم إبليس على الكفر، وإنَّما كان منه الدعاء والتزيين... لم تكن له حجة يتتبعهم بها، وإنَّما اتبعوه بشهوة وتقليد وهوى نفس لا عن حجة ودليل. البغوي:٣/٦٠٤.\nهل لإبليس قوة يقهر بها الإنسان على الكفر والمعاصي؟"],[431,"§سبإ\nwords\nفُزِّعَزَالَ الفَزَعُ عَن قُلُوبِهِم.\nيَفتَحُيَقضِي.\nبِالحَقِّبِالعَدلِ.\nالفَتَّاحُالحَاكِمُ بَينَ خَلقِهِ.\nوَلاَ بِالَّذِي بَينَ يَدَيهِوَلاَ بِالَّذِي تَقَدَّمَهُ مِنَ التَّورَاةِ وَالإِنجِيلِ وَالزَّبُورِ.\nمَوقُوفُونَ مَحبُوسُونَ فِي مَوقِفِ الحِسَابِ.\nيَرجِعُيَرُدُّ بَعضُهُم عَلَى بَعضٍ.\ndeeds\nادع الله أن يشفعك فيمن تحب.\nسَلِ الله سبحانه أن يُشَفِّع فيك أنبياءه وملائكته وصالحي خلقه، ولا تسألها من أحدٍ غيره كائنًا من كان.\nاشكر الله -سبحانه وتعالى- على رزقه الذي رزقك إياه.\nguid\nسَلِ الله أن يملأ قلبك من خشيته وتعظيمه ومحبته.\nتذكر أن الرازق هو الله وحده، فلا تسأل سواه.\nاستخدم في دعوتك التبشير بالخير، والإنذار من الشر.\nrefl\nوَلَا تَنفَعُ ٱلشَّفَٰعَةُ عِندَهُۥٓ إِلَّا لِمَنۡ أَذِنَ لَهُۥۚ\nوهذا تنبيه من الله تعالى وإخبار أن الملائكة مع اصطفائهم ورفعتهم لا يمكنهم أن يشفعوا لأحد حتى يؤذن لهم، فإذا أذن لهم وسمعوا صعقوا، وكانت هذه حالهم؛ فكيف تشفع الأصنام؟! أو كيف تؤملون أنتم الشفاعة ولا تعترفون بالقيامة؟! القرطبي:١٧/٣١١.\nبيّن عظم أمر الشفاعة عند الله يوم القيامة من هذه الآية.\nحَتَّىٰٓ إِذَا فُزِّعَ عَن قُلُوبِهِمۡ قَالُواْ مَاذَا قَالَ رَبُّكُمۡۖ قَالُواْ ٱلۡحَقَّۖ وَهُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ ٢٣\nتظاهرت الأحاديث عن رسول الله أن هذه الآية في الملائكة -عليهم السلام- فإنهم إذا سمعوا الوحي إلى جبريل يفزعون لذلك فزعًا عظيمًا، فإذا زال الفزع عن قلوبهم قال بعضهم لبعض: ماذا قال ربكم؟ فيقولون: قال الحق. ابن جزي:٢/٢٠٥.\nفي هذه الآية دليل على عظَمة الوحي، بيّن ذلك.\nحَتَّىٰٓ إِذَا فُزِّعَ عَن قُلُوبِهِمۡ قَالُواْ مَاذَا قَالَ رَبُّكُمۡۖ قَالُواْ ٱلۡحَقَّۖ وَهُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ ٢٣\nوتخصيص هاتين الصفتين لمناسبة مقام الجواب، أي: قد قضى بالحق لكل أحد بما يستحقه؛ فإنه لا يخفى عليه حال أحد، ولا يعوقه عن إيصاله إلى حقه عائق. ابن عاشور:٢٢/١٩٠- ١٩١.\nما فائدة تخصيص صفتي: ﴿ٱلۡعَلِيُّ ٱلۡكَبِيرُ﴾ بالذكر في الآية الكريمة؟\nوَإِنَّآ أَوۡ إِيَّاكُمۡ لَعَلَىٰ هُدًى أَوۡ فِي ضَلَٰلٖ مُّبِينٖ ٢٤\nأي: واحد من الفريقين مبطل، والآخر محق؛ لا سبيل إلى أن تكونوا أنتم ونحن على الهدى أو على الضلال، بل واحد منا مصيب. ابن كثير:٣/٥١٦.\nما رأيك فيمن يهون من الخلافات بين الفرق وبين الديانات، ويرى أن كل واحد مصيب؟\nقُلۡ يَجۡمَعُ بَيۡنَنَا رَبُّنَا ثُمَّ يَفۡتَحُ بَيۡنَنَا بِٱلۡحَقِّ وَهُوَ ٱلۡفَتَّاحُ ٱلۡعَلِيمُ ٢٦\nوإنَّما أتبع (الفتاح) ب(العليم) للدلالة على أن حكمه عدلٌ مَحض؛ لأنه عليم لا تحفّ بحكمه أسباب الخطأ والجور الناشئة عن الجهل والعجز واتباع الضعف النفساني الناشئ عن الجهل بالأحوال والعواقب. ابن عاشور:٢٢/١٩٥.\nلماذا أتبع اسمه تعالى (الفتاح) باسمه سبحانه (العليم)؟\nوَمَآ أَرۡسَلۡنَٰكَ إِلَّا كَآفَّةٗ لِّلنَّاسِ بَشِيرٗا وَنَذِيرٗا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ٢٨\nهذا إعلام من الله تعالى بأنه بعث محمدًا -صلى الله عليه وسلم- إلى جميع العالم... وهذه إحدى الخصال التي خص بها محمد -صلى الله عليه وسلم- من بين الأنبياء. ابن عطية:٤/٤٢٠.\nذكرت الآية خصلة مما خص به نبينا محمد -صلى الله عليه وسلم-؛ فما هي؟\nوَلَوۡ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ مَوۡقُوفُونَ عِندَ رَبِّهِمۡ يَرۡجِعُ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ ٱلۡقَوۡلَ يَقُولُ ٱلَّذِينَ ٱسۡتُضۡعِفُواْ لِلَّذِينَ ٱسۡتَكۡبَرُواْ لَوۡلَآ أَنتُمۡ لَكُنَّا مُؤۡمِنِينَ ٣١\n﴿وَلَوۡ تَرَىٰٓ﴾ يا محمد ﴿إِذِ ٱلظَّٰلِمُونَ مَوۡقُوفُونَ عِندَ رَبِّهِمۡ﴾ أي: محبوسون في موقف الحساب، يتراجعون الكلام فيما بينهم باللوم والعتاب بعد أن كانوا في الدنيا أخلاء متناصرين. وجواب (لو) محذوف؛ أي: لرأيت أمرًا هائلًا فظيعًا. القرطبي:١٧/٣١٦\nصف حال الأخلاء من المشركين إذا وقفوا بين يدي الله تعالى."],[432,"§سبإ\nwords\nالنَّدَامَةَالتَّحَسُّرَ.\nيَبسُطُيُوسِعُ.\nزُلفَىقُربَى.\nالغُرُفَاتِ المَنَازِلِ الرَّفِيعَةِ فِي الجَنَّةِ.\nمُعَاجِزِينَمُشَاقِّينَ يَظُنُّونَ أَنَّهُم يَفُوتُونَنَا.\nمُحضَرُونَتُحضِرُهُمُ الزَّبَانِيَةُ إِلَى جَهَنَّمَ.\nوَيَقدِرُ لَهُيُضَيِّقُهُ عَلَيهِ.\ndeeds\nصم يومًا في سبيل الله.\nقل: \"اللهم اجعلنا عند النعماء من الشاكرين، وعند البلاء من الصابرين\".\nأنفق من مالك في دعم مشروع دعوي راجيًا الخلف من الله تعالى.\nguid\nتجنب طاعة الكبراء في الباطل.\nاحذر من صداقة أهل النفاق الذين يمكرون ويحاولون صدك عن طاعة الله بأنواع الحيل.\nتذكر أن أهل الكفر والعصيان سيندمون أشد الندم إذا عاينوا العذاب.\nrefl\nقَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ لِلَّذِينَ ٱسۡتُضۡعِفُوٓاْ أَنَحۡنُ صَدَدۡنَٰكُمۡ عَنِ ٱلۡهُدَىٰ بَعۡدَ إِذۡ جَآءَكُمۖ بَلۡ كُنتُم مُّجۡرِمِينَ ٣٢\nأي: نحن ما فعلنا بكم أكثر من أنَّا دعوناكم فاتبعتمونا من غير دليل ولا برهان، وخالفتم الأدلة والبراهين والحجج التي جاءت بها الرسل لشهوتكم واختياركم؛ ولهذا قالوا: ﴿بَلۡ كُنتُم مُّجۡرِمِينَ﴾. ابن كثير:٣/٥١٨.\nلماذا وُصِفَ المستضعفون بالمجرمين؟\nوَقَالَ ٱلَّذِينَ ٱسۡتُضۡعِفُواْ لِلَّذِينَ ٱسۡتَكۡبَرُواْ بَلۡ مَكۡرُ ٱلَّيۡلِ وَٱلنَّهَارِ إِذۡ تَأۡمُرُونَنَآ أَن نَّكۡفُرَ بِٱللَّهِ وَنَجۡعَلَ لَهُۥٓ أَندَادٗاۚ\nالمعنى: أن المستضعفين قالوا للمستكبرين: بل مكركم بنا في الليل والنهار سبب كفرنا. ابن جزي:٢/٢٠٧.\nكل ولاء وتبعيّة مبنيّة على غير شرع الله تنقلب إلى عداوة، مثّل لهذا من خلال الآية.\nوَقَالَ ٱلَّذِينَ ٱسۡتُضۡعِفُواْ لِلَّذِينَ ٱسۡتَكۡبَرُواْ بَلۡ مَكۡرُ ٱلَّيۡلِ وَٱلنَّهَارِ إِذۡ تَأۡمُرُونَنَآ أَن نَّكۡفُرَ بِٱللَّهِ وَنَجۡعَلَ لَهُۥٓ أَندَادٗاۚ\nهذه مراجعة من الأتباع للرؤساء حين قالوا لهم: إنَّما كفرتم ببصائر أنفسكم، قال المستضعفون: بل كفرنا بمكركم بنا بالليل والنهار، وأضاف المكر إلى الليل والنهار...لتدل هذه الإضافة على الدُّؤوب والدوام. ابن عطية:٤/٤٢١.\nما رد المستضعفين على رؤسائهم المضلين يوم القيامة؟\nوَأَسَرُّواْ ٱلنَّدَامَةَ لَمَّا رَأَوُاْ ٱلۡعَذَابَۚ\nأي: زال عنهم ذلك الاحتجاج الذي احتج به بعضهم على بعض لينجو من العذاب، وعلم أنه ظالم مستحق له، فندم كل منهم غاية الندم، وتمنى أن لو كان على الحق، وأنه ترك الباطل -الذي أوصله إلى هذا العذاب- سرًّا في أنفسهم؛ لخوفهم من الفضيحة في إقرارهم على أنفسهم. السعدي:٦٨١.\nلماذا لم يجهر الكافرون بالندامة يوم القيامة؟\nوَقَالُواْ نَحۡنُ أَكۡثَرُ أَمۡوَٰلٗا وَأَوۡلَٰدٗا وَمَا نَحۡنُ بِمُعَذَّبِينَ ٣٥\nأي: افتخروا بكثرة الأموال والأولاد، واعتقدوا أن ذلك دليل على محبة الله تعالى لهم واعتنائه بهم، وأنه ما كان ليعطيهم هذا في الدنيا ثم يعذبهم في الآخرة. ابن كثير:٣/٥١٩.\nلماذا ربط الكفار بين كثرة الأموال والأولاد وعدم العذاب؟\nقُلۡ إِنَّ رَبِّي يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ٣٦\nإخبار يتضمن الردّ عليهم بأن بسط الرزق وقبضه في الدنيا معلق بمشيئة الله؛ فقد يوسع الله على الكافر وعلى العاصي، ويضيق على المؤمن والمطيع، وبالعكس، فليس في ذلك دليل على أمر الآخرة. ابن جزي:٢/ ٢٠٨.\nما سنة الله في تقسيم الرزق؟ وهل هي مقياس حقيقيّ للنجاة في الآخرة؟\nوَمَآ أَنفَقۡتُم مِّن شَيۡءٖ فَهُوَ يُخۡلِفُهُۥۖ وَهُوَ خَيۡرُ ٱلرَّٰزِقِينَ ٣٩\nقال ابن العربي: \"قد يعوّض مثله أو أَزْيَدَ، وقد يعوض ثوابًا، وقد يُدَّخر له؛ وهو كالدعاء في وعد الإِجابة\" اه. قلت: وقد يعوّض صحة، وقد يعوّض تعميرًا؛ ولله في خلقه أسرار. ابن عاشور:٢٢/٢٢١.\nاذكر أنواعًا مما يخلفه الله تعالى على عبده إذا أنفق."],[433,"§سبإ\nwords\nيَدرُسُونَهَايَقرَؤُونَهَا.\nنَكِيرِإِنكَارِي عَلَيهِم.\nبِوَاحِدَةٍبِخَصلَةٍ وَاحِدَةٍ.\nمَثنَىاثنَينِ اثنَينِ.\nجِنَّةٍجُنُونٍ.\nيَقذِفُ بِالحَقِّيَرمِي بِحُجَجِ الحَقِّ عَلَى البَاطِلِ؛ فَيَدمَغُهُ.\ndeeds\nانطق بشهادة التوحيد، قاصدًا التبرؤ من كل معبود سوى الله -سبحانه وتعالى-.\nا رسل رسالة إلى أهلك أو زملائك للتحذير من السحر والذهاب إلى السحرة، مبيّنًا أن هذا منافٍ لعبادة الله.\nفرّغ وقتًا لنفسك، واقرأ سورةً من سور القرآن الكريم.\nguid\nنزه الله تعالى، وسبحه، وعظمه، وخاصة عند سماع ما ينقص من عظمته وجلاله؛ اقتداء بالملائكة المقربين.\nأحْيِ في نفسك عبادة التفكر؛ فهي من أجلِّ العبادات القلبية.\nلا تجعل الدين سلمًا تنال به عرض الدنيا الزائل؛ فإن الآخرة خير وأبقى.\nrefl\nوَيَوۡمَ يَحۡشُرُهُمۡ جَمِيعٗا ثُمَّ يَقُولُ لِلۡمَلَٰٓئِكَةِ أَهَٰٓؤُلَآءِ إِيَّاكُمۡ كَانُواْ يَعۡبُدُونَ ٤٠\nيخبر تعالى أنه يقرع المشركين يوم القيامة على رؤوس الخلائق؛ فيسأل الملائكة: ﴿أَهَٰٓؤُلَآءِ إِيَّاكُمۡ كَانُواْ يَعۡبُدُونَ﴾. ابن كثير:٣/٥٢٠.\nما الحكمة من سؤال الملائكة يوم القيامة عن عبادة المشركين لهم؟\nوَيَوۡمَ يَحۡشُرُهُمۡ جَمِيعٗا ثُمَّ يَقُولُ لِلۡمَلَٰٓئِكَةِ أَهَٰٓؤُلَآءِ إِيَّاكُمۡ كَانُواْ يَعۡبُدُونَ ٤٠\nوالاقتصار على تقرير الملائكة واستشهادهم على المشركين لأن إبطال إلاهية الملائكة يفيد إبطال إلاهية ما هو دونها ممن [عُبِد] من دون الله بدلالة الفحوى، أي بطريق الأولى؛ فإن ذلك التقرير من أهم ما جعل الحشر لأجله. ابن عاشور:٢٢/٢٢٢.\nما فائدة الاقتصار على تقرير الملائكة، واستشهادهم على المشركين يوم القيامة؟\nوَكَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ وَمَا بَلَغُواْ مِعۡشَارَ مَآ ءَاتَيۡنَٰهُمۡ فَكَذَّبُواْ رُسُلِيۖ فَكَيۡفَ كَانَ نَكِيرِ ٤٥\nأي: أعطينا الأمم الخالية من القوة والنعمة وطول العمر ﴿فَكَذَّبُواْ رُسُلِيۖ فَكَيۡفَ كَانَ نَكِيرِ﴾ أي: إنكاري وتغييري عليهم؛ يحذر كفار هذه الأمة عذاب الأمم الماضية. البغوي:٣/٦١١.\nبيّن السر في إشارة القرآن للأمم القوية المكذبة من قبل أمة محمد -صلى الله عليه وسلم-\nوَكَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ وَمَا بَلَغُواْ مِعۡشَارَ مَآ ءَاتَيۡنَٰهُمۡ فَكَذَّبُواْ رُسُلِيۖ فَكَيۡفَ كَانَ نَكِيرِ ٤٥\nومعناه: أن تقوموا للنظر في أمر محمد -صلى الله عليه وسلم- قيامًا خالصًا لله تعالى، ليس فيه اتباع هوى ولا ميل. وليس المراد بالقيام هنا القيام على الرجلين، وإنَّما المراد القيام بالأمر والجدّ فيه. ابن جزي:٢/٢٠٩.\nمتى يكون القيام بأمر الله خالصًا؟ ومتى يكون باطلًا؟\n۞قُلۡ إِنَّمَآ أَعِظُكُم بِوَٰحِدَةٍۖ أَن تَقُومُواْ لِلَّهِ مَثۡنَىٰ وَفُرَٰدَىٰ ثُمَّ تَتَفَكَّرُواْۚ مَا بِصَاحِبِكُم مِّن جِنَّةٍۚ إِنۡ هُوَ إِلَّا نَذِيرٞ لَّكُم بَيۡنَ يَدَيۡ عَذَابٖ شَدِيدٖ ٤٦\n﴿ثُمَّ تَتَفَكَّرُواْۚ﴾ هل جربتم على صاحبكم كذبًا، أو رأيتم فيه جِنة، أو في أحواله مِن فساد، أو اختلف إلى أحد ممن يدَّعي العلم بالسحر، أو تعلم الأقاصيص وقرأ الكتب، أو عرفتموه بالطمع في أموالكم، أو تقدرون على معارضته في سورة واحدة؟! فإذا عرفتم بهذا الفكر صدقه؛ فما بال هذه المعاندة؟! ﴿فَهُوَ لَكُمۡۖ﴾ أي فأشهدكم أن ذلك الأجر -على التقدير- أنه لكم. القرطبي:١٧/٣٣٠.\nما التفكر الذي طلب منهم؟ وكيف نعرف بذلك الحق من الباطل؟\nقُلۡ مَا سَأَلۡتُكُم مِّنۡ أَجۡرٖ فَهُوَ لَكُمۡۖ\nوثَمَّ مانع للنفوس آخر من اتباع الداعي إلى الحق، وهو: أنه يأخذ أموال من يستجيب له، ويأخذ أجرة على دعوته، فبيَّن الله تعالى نزاهة رسوله -صلى الله عليه وسلم- عن هذا الأمر، فقال: ﴿قُلۡ مَا سَأَلۡتُكُم مِّنۡ أَجۡرٍ﴾ أي: على اتباعكم للحق. السعدي:٦٨٣.\nبيّن الله -عز وجل- في هذه الآية علامة من علامات الدعاة الصادقين؛ فما هي؟\nقُلۡ إِنَّ رَبِّي يَقۡذِفُ بِٱلۡحَقِّ عَلَّٰمُ ٱلۡغُيُوبِ ٤٨\nوتخصيص وصف ﴿عَلَّٰمُ ٱلۡغُيُوبِ﴾ من بين الأوصاف الإِلهية؛ للإِشارة إلى أنه عالم بالنوايا، وأن القائِل يعلم ذلك، فالذي يعلم هذا لا يجترئ على الله بادعائه باطلًا أنه أرسله إليكم. ابن عاشور:٢٢/٢٣٨.\nما فائدة تخصيص وصف ﴿عَلَّٰمُ ٱلۡغُيُوبِ﴾ في الآية الكريمة؟"],[434,"§سبإ ، فاطر\nwords\nفَزِعُواخَافُوا عِندَ مُعَايَنَةِ العَذَابِ.\nفَلاَ فَوتَفَلاَ نَجَاةَ لَهُم، وَلاَ مَهرَبَ.\nوَأَنَّى لَهُمُ التَّنَاوُشُكَيفَ لَهُم تَنَاوُلُ الإِيمَانِ، وَهُم فِي الآخِرَةِ؟!\nوَيَقذِفُونَ بِالغَيبِيَرمُونَ بِالظُّنُونِ الكَاذِبَةِ.\nبِأَشيَاعِهِمأَمثَالِهِم مِن كُفَّارِ الأُمَمِ السَّابِقَةِ.\nفَأَنَّى تُؤفَكُونَكَيفَ تُصرَفُونَ عَن تَوحِيدِهِ؟!\ndeeds\nقل: \"اللهم اجعل القرآن العظيم ربيع قلبي، ونور صدري، وجلاء حزني، وذهاب همي\".\nتذكر كلمة محرمة قلتها ثم استغفر الله تعالى منها.\nاجمع خمسًا من صفات الملائكة من خلال آيات القرآن الكريم.\nguid\nعلمك بصفتي الله سبحانه: (السميع) و (القريب) يدعوك إلى استشعار إجابة الله لك وقربه منك.\nمن الآن استقم على طاعة الله، والزم العبادات قبل أن تشتهي ذلك فيحال بينك وبينه.\nتأمل في عظيم خلق الله تعالى للملائكة، ومع ذلك فهم في غاية الذلة والانكسار لله تعالى.\nrefl\nوَلَوۡ تَرَىٰٓ إِذۡ فَزِعُواْ فَلَا فَوۡتَ وَأُخِذُواْ مِن مَّكَانٖ قَرِيبٖ ٥١\n﴿وَلَوۡ تَرَىٰٓ إِذۡ فَزِعُواْ﴾: في الدنيا عند نزول الموت أو غيره من بأس الله تعالى بهم... وقيل: هو فزعهم في القبور من الصيحة. القرطبي:١٧/٣٣٣.\nكيف يكون حال الكافر إذا عاين الحقائق المخيفة؟\nوَيَقۡذِفُونَ بِٱلۡغَيۡبِ مِن مَّكَانِۢ بَعِيدٖ ٥٣\nبقذفهم الباطل؛ ليدحضوا به الحق، ولكن لا سبيل إلى ذلك؛ كما لا سبيل للرامي من مكان بعيد إلى إصابة الغرض، فكذلك الباطل من المحال أن يغلب الحق أو يدفعه، وإنَّما يكون له صولة وقت غفلة الحق عنه، فإذا برز الحق وقاوم الباطل قمعه. السعدي:٦٨٤.\nلماذا وصف رمي أهل الباطل للحقَّ بأنه من مكان بعيد؟\nوَحِيلَ بَيۡنَهُمۡ وَبَيۡنَ مَا يَشۡتَهُونَ كَمَا فُعِلَ بِأَشۡيَاعِهِم مِّن قَبۡلُۚ إِنَّهُمۡ كَانُواْ فِي شَكّٖ مُّرِيبِۢ ٥٤\nأي: حيل بينهم وبين دخول الجنة، وقيل: حيل بينهم وبين الانتفاع بالإيمان حينئذ، وقيل: حيل بينهم وبين نعيم الدنيا والرجوع إليها. ابن جزي:٢/٢١٠.\nما الأمر الذي اشتهاه الكفار وحيل بينهم وبينه؟\nوَحِيلَ بَيۡنَهُمۡ وَبَيۡنَ مَا يَشۡتَهُونَ كَمَا فُعِلَ بِأَشۡيَاعِهِم مِّن قَبۡلُۚ إِنَّهُمۡ كَانُواْ فِي شَكّٖ مُّرِيبِۢ ٥٤\nوفائدة هذا التشبيه: تذكير الأحياء منهم -وهم مشركو أهل مكة- بما حل بالأمم من قبلهم؛ ليُوقنوا أن سنة الله واحدة، وأنهم لا تنفعهم أصنامهم التي زعموها شفعاء عند الله. ابن عاشور:٢٢/٢٤٥.\nما فائدة التشبيه في الآية الكريمة؟\nٱلۡحَمۡدُ لِلَّهِ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ جَاعِلِ ٱلۡمَلَٰٓئِكَةِ رُسُلًا أُوْلِيٓ أَجۡنِحَةٖ مَّثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۚ يَزِيدُ فِي ٱلۡخَلۡقِ مَا يَشَآءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ١\nافتتاحها بـ﴿ٱلۡحَمۡدُ لِلَّهِ﴾ مؤذن بأن صفات من عظمة الله ستذكر فيها، وإجراء صفات الأفعال على اسم الجلالة؛ مِن خلقِهِ السماوات والأرض -وأفضلِ ما فيها من الملائكة والمرسلين- مؤذن بأن السورة جاءت لإِثبات التوحيد وتصديق الرسول -صلى الله عليه وسلم-. ابن عاشور:٢٢/٢٤٨.\nلماذا افتتحت سورة فاطر بالحمد لله؟\nمَّا يَفۡتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحۡمَةٖ فَلَا مُمۡسِكَ لَهَاۖ وَمَا يُمۡسِكۡ فَلَا مُرۡسِلَ لَهُۥ مِنۢ بَعۡدِهِۦۚ\n﴿مَّا يَفۡتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحۡمَةٍ﴾: قيل: من مطر ورزق. ﴿فَلَا مُمۡسِكَ لَهَاۖ﴾: لا يستطيع أحد على حبسها. ﴿وَمَا يُمۡسِكۡ فَلَا مُرۡسِلَ لَهُۥ مِنۢ بَعۡدِهِۦۚ﴾: وهو (العزيز) فيما أمسك، (الحكيم) فيما أرسل. البغوي ٣/٦١٦.\nهل يستطيع أحد من الخلق إمساك شيء كتبه الله لك؟\nيَٰٓأَيُّهَا ٱلنَّاسُ ٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡۚ هَلۡ مِنۡ خَٰلِقٍ غَيۡرُ ٱللَّهِ يَرۡزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ لَآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ ٣\nينبه تعالى عباده ويرشدهم إلى الاستدلال على توحيده في إفراد العبادة له، كما أنه المستقل بالخلق والرزق، فكذلك فليفرَد بالعبادة ولا يشرَك به غيره من الأصنام والأنداد والأوثان. ابن كثير:٣/٥٢٥.\nما علاقة الخلق والرزق بتوحيد العبادة؟"],[435,"§فاطر\nwords\nفَلاَ تَغُرَّنَّكُمُلاَ تَخدَعَنَّكُم، وَلاَ تُلهِيَنَّكُم.\nالغَرُورُالشَّيطَانُ.\nفَلاَ تَذهَبنَفسُكَ فَلاَ تُهلِكهَا.\nحَسَرَاتٍحُزنًا عَلَى كُفرِ هَؤُلاَءِ الضَّالِّينَ.\nفَتُثِيرُتُحَرِّكُ.\nيَبُورُيَفسُدُ، وَيَبطُلُ.\nمُعَمَّرٍطَوِيلِ العُمُرِ.\ndeeds\nقل: \"اللهم لا تجعل الدنيا أكبر همي ولا مبلغ علمي، ولا إلى النار مصيري\".\nتذكر عداوة الشيطان لك كل صباح ومساء، واستعذ بالله منه، وكن على حذر.\nأمط الأذى عن الطريق، أو ساعد محتاجًا بجهدك أو بمالك؛ ابتغاء وجه الله.\nguid\nمن العزاء للداعية أن الإعراض والتكذيب قد وقع للرسل من قبله.\nمن استشعر العداوة لزم الحذر.\nالزم السنة والدليل الصحيح، واحذر البدعة واتباع اهلوى والعاطفة؛ حتى لا تكون ممن زين له سوء عمله فرآه حسنًا.\nrefl\nيَٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعۡدَ ٱللَّهِ حَقّ\nفإذا كان وعده حقًا؛ فتهيؤوا له، وبادروا أوقاتكم الشريفة بالأعمال الصالحة، ولا يقطعكم عن ذلك قاطع. السعدي:٦٨٥.\nإذا علمت أن وعد الله حق فما الذي ينبغي عليك أن تعمله؟\nيَٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ ٥\nقال سعيد بن جبير: \"غرور الحياة الدنيا: أن يشتغل الإنسان بنعيمها ولذاتها عن عمل الآخرة، حتى يقول:﴿يَٰلَيۡتَنِي قَدَّمۡتُ لِحَيَاتِي﴾ [الفجر: ٢٤]\". القرطبي:١٧/٣٤٦.\nبيّن كيف يكون الاغترار بالحياة الدنيا.\nيَٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ ٥\nوقد تضمنت الآية غرورين: غرورًا يغتَرّه المرء من تلقاء نفسه، ويزيّن لنفسه من المظاهر الفاتنة التي تلوح له في هذه الدنيا ما يتوهمه خيرًا، ولا ينظر في عواقبه؛ بحيث تخفى مضارّه في بادئ الرأي، ولا يظنّ أنه من الشيطان، وغرورًا يتلقاه ممن يغرّه وهو الشيطان. وكذلك الغرور كله في هذا العالم: بعضه يمليه المرء على نفسه، وبعضه يتلقاه من شياطين الإِنس والجن. ابن عاشور:٢٢/٢٥٩.\nتضمنت الآية الكريمة التحذير من غرورين، فما هما؟\nإِنَّ ٱلشَّيۡطَٰنَ لَكُمۡ عَدُوّٞ فَٱتَّخِذُوهُ عَدُوًّاۚ إِنَّمَا يَدۡعُواْ حِزۡبَهُۥ لِيَكُونُواْ مِنۡ أَصۡحَٰبِ ٱلسَّعِيرِ ٦\nفعداوة الشيطان لمَّا كانت جبلّية لا يرجى زوالها مع من يعفو عنه، لم يأمر الله إلا باتخاذه عدوًّا؛ لأنه إذا لم يُتخَذ عدوًّا لم يراقب المسلم مكائده ومخادعته. ومن لوازم اتخاذه عدوًّا: العملُ بخلاف ما يدعو إليه؛ لتجنب مكائده، ولمقته بالعمل الصالح. ابن عاشور:٢٢/٢٦١.\nلماذا أمر الله سبحانه باتخاذ الشيطان عدوًا مطلقًا، ولم يأمر بالصفح أو العفو عنه؟\nإِنَّ ٱلشَّيۡطَٰنَ لَكُمۡ عَدُوّٞ فَٱتَّخِذُوهُ عَدُوًّاۚ إِنَّمَا يَدۡعُواْ حِزۡبَهُۥ لِيَكُونُواْ مِنۡ أَصۡحَٰبِ ٱلسَّعِيرِ ٦\nأي: عادوه بطاعة الله، ولا تطيعوه... وكان الفضيل بن عياض يقول: \"يا كذاب يا مفتر، اتق الله، ولا تسب الشيطان في العلانية وأنت صديقه في السر\"، وقال ابن السماك: \"يا عجبًا لمن عصى المحسن بعد معرفته بإحسانه، وأطاع اللعين بعد معرفته بعداوته\". البغوي:٣/٦١٦، القرطبي:١٧/٣٤٧\nكيف تعادي عدو الله إبليس كما أمرك الله تعالى؟\nمَن كَانَ يُرِيدُ ٱلۡعِزَّةَ فَلِلَّهِ ٱلۡعِزَّةُ جَمِيعًاۚ\nأي: يا من يريد العزة؛ اطلبها ممن هي بيده؛ فإن العزة بيد الله، ولا تنال إلا بطاعته. السعدي:٦٨٥.\nما الذي يفيده المسلم من معرفة أن العزة لله جميعا؟\nمَن كَانَ يُرِيدُ ٱلۡعِزَّةَ فَلِلَّهِ ٱلۡعِزَّةُ جَمِيعًاۚ\nالآية تحتمل ثلاثة معان؛ أحدها -وهو الأظهر-: من كان يريد نيل العزة فليطلبها من عند الله؛ فإن العزة كلها لله. والثاني: من كان يريد العزة بمغالبة الإسلام؛ فللَّه العزة جميعًا؛ فالمغالب له مغلوب. والثالث: من كان يريد أن يعلم لمن العزة؛ فليعلم أن العزة لله جميعًا. ابن جزي:٢/٢١٢.\nبيّن الله الطريق لطالب العزة، وضحه."],[436,"§فاطر\nwords\nفُرَاتٌشَدِيدُ العُذُوبَةِ.\nسَائِغٌسَهلٌ مُرُورُهُ فِي الحَلقِ.\nأُجَاجٌشَدِيدُ المُلُوحَةِ.\nمَوَاخِرَتَشُقُّ المِيَاهَ.\nقِطمِيرٍهِيَ: القِشرَةُ الرَّقِيقَةُ البَيضَاءُ عَلَى النَّوَاةِ.\nمُثقَلَةٌنَفسٌ مُثقَلَةٌ بِالخَطَايَا.\nحِملِهَاذُنُوبِهَا الَّتي أَثقَلَتهَا.\ndeeds\nقل: \"اللهم آت نفسي تقواها، وزكها أنت خير من زكاها؛ أنت وليها ومولاها\".\nاقرأ كتابًا عن أعمال القلوب وأهميتها.\nتصدق بشيء من مالك، أو قم هذه الليلة بصلاة، أو اقرأ القرآن الكريم.\nguid\nاحذر من دعاء غير الله تعالى.\nالله سبحانه أقرب إلى القلوب المنكسرة له.\nاحرص على الاتعاظ والاستفادة من الوعظ والتذكير؛ تكن من أهل خشية الله تعالى.\nrefl\nوَٱلَّذِينَ تَدۡعُونَ مِن دُونِهِۦ مَا يَمۡلِكُونَ مِن قِطۡمِيرٍ ١٣\nأي: لا يملكون شيئًا؛ لا قليلًا ولا كثيرًا، حتى ولا القطمير الذي هو أحقر الأشياء، فكيف يُدعَون وهم غير مالكين لشيء من ملك السماوات والأرض؟! السعدي:٦٨٦.\nما الفائدة التي يستفيدها الإنسان من معرفة أن ما يُدعى من دون الله لا يملك شيئًا؟\nإِن تَدۡعُوهُمۡ لَا يَسۡمَعُواْ دُعَآءَكُمۡ وَلَوۡ سَمِعُواْ مَا ٱسۡتَجَابُواْ لَكُمۡۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُونَ بِشِرۡكِكُمۡۚ وَلَا يُنَبِّئُكَ مِثۡلُ خَبِيرٖ ١٤\nولما كشف حال الأصنام في الدنيا بما فيه تأييس من انتفاعهم بها... كشف أمرها في الآخرة بأن تلك الأصنام ينطقها الله؛ فتتبرأ من شركهم؛ أي: تتبرأ من أن تكون دعت له، أو رضيت به. ابن عاشور:٢٢/٢٨٣.\nكيف أظهر الله سبحانه بطلان عبادة الأصنام في الدنيا والآخرة؟\n۞يَٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلۡفُقَرَآءُ إِلَى ٱللَّهِۖ وَٱللَّهُ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ ١٥\nلَمَّا أُشبِعَ المَقَام أَدلَّةً، ومواعظَ... ولَم يظهر مع ذلكَ كُلِّه من أَحوالِ القَومِ ما يُتَوَسَّمُ منه نزعهم عن ضلالهِم، وربما أحدث ذلك في نفوس أهل العزّة منهم إعجابًا بأنفسهم، واغترارًا بأنهم مرغوب في انضمامهم إلى جماعة المسلمين؛ فيزيدهم ذلك الغرورُ قبولًا لتسويل مكائد الشيطان لهم أن يعتصموا بشركهم، ناسب أن ينبئهم الله بأنه غني عنهم، وأن دينه لا يعتزّ بأمثالهم، وأنه مُصيِّرهم إلى الفناء، وآت بناس يعتز بهم الإِسلام. ابن عاشور:٢٢/٢٨٥.\nما الحكمة من وصف عموم الناس بالفقر في هذه الآية؟\n۞يَٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلۡفُقَرَآءُ إِلَى ٱللَّهِۖ\nيخاطب تعالى جميع الناس، ويخبرهم بحالهم ووصفهم، وأنهم فقراء إلى الله من جميع الوجوه: فقراء في إيجادهم؛ فلولا إيجاده إياهم لم يوجدوا، فقراء في إعدادهم بالقوى والأعضاء والجوارح التي لولا إعداده إياهم بها لما استعدوا لأي عمل كان، فقراء في إمدادهم بالأقوات والأرزاق والنعم الظاهرة والباطنة؛ فلولا فضله وإحسانه وتيسيره الأمور لما حصل لهم من الرزق والنعم شيء، فقراء في صرف النقم عنهم ودفع المكاره وإزالة الكروب والشدائد؛ فلولا دفعه عنهم وتفريجه لكرباتهم وإزالته لعسرهم لاستمرت عليهم المكاره والشدائد. السعدي:٦٨٧.\nهل فقر الناس إلى الله هو في المال فقط؟ بيِّن شيئًا من أوجه الفقر التي يفتقر الناس فيها إلى ربهم.\n۞يَٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلۡفُقَرَآءُ إِلَى ٱللَّهِۖ وَٱللَّهُ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ ١٥\nلما أثبت فقرهم إليه وغناه عنهم، وليس كل غني نافعًا بغناه إلا إذا كان الغني جوادًا منعمًا... ذكر (الحميد) ليدل به على أنه الغني النافع بغناه خلقه، الجواد المنعم عليهم. القرطبي:١٧/٣٦٦\nلمَ قرن صفة (الغني) بصفة (الحميد) في الآية؟\nوَإِن تَدۡعُ مُثۡقَلَةٌ إِلَىٰ حِمۡلِهَا لَا يُحۡمَلۡ مِنۡهُ شَيۡءٞ وَلَوۡ كَانَ ذَا قُرۡبَىٰٓۗ\nقال ابن عباس -رضي الله عنهما-: \"يَلقَى الأب والأم ابنه فيقول: يا بني احمل عني بعض ذنوبي، فيقول: لا أستطيع؛ حسبي ما علي\". البغوي:٣/٦٢١.\nمن سيحمل عنك ذنوبك يوم القيامة؟\nإِنَّمَا تُنذِرُ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ وَأَقَامُواْ ٱلصَّلَوٰةَۚ وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفۡسِهِۦۚ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ ١٨\nالمعنى: أن الإنذار لا ينفع إلا الذين يخشون ربهم، وليس المعنى اختصاصهم بالإنذار.ابن جزي:٢/٢١٥.\nهل تدل الآية على أن الرسل والدعاة لا ينذرون إلا أهل الخشية؟ وضح ذلك."],[437,"§فاطر\nwords\nالحَرُورُالرِّيحُ الحَارَّةُ.\nوَبِالزُّبُرِالكُتُبِ المَجمُوعِ فِيهَا كَثِيرٌ مِنَ الأَحكَامِ.\nنَكِيرِإِنكَارِي عَلَيهِم، وَعُقُوبَتِي لَهُم.\nجُدَدٌذَاتُ طَرَائِقَ وَخُطُوطٍ مُختَلِفَةِ الأَلوَانِ.\nوَغَرَابِيبُ سُودٌشَدِيدَةُ السَّوَادِ؛ كَالأَغرِبَةِ.\nلَن تَبُورَلَن تَكسُدَ، وَتَهلِكَ.\ndeeds\nابتداء من اليوم خصص لك مقدارًا من القرآن ولو قصيرًا تقرأه كل يوم.\nأَدِّ الصلاة جماعة مع إدراك التكبيرة الأولى.\nتصدق من مالك بصدقة لا يعلم عنها أحد إلا الله، وتصدق بصدقة أخرى علانية؛ لعله يقتدي بك غيرك.\nguid\nحقق خشية الله تعالى في حياتك تكن من أهل العلم حقيقة.\nأكثر من تلاوة القرآن معتبرًا متفكرًا.\nتذكر دائمًا أن التجارة التي لا تبور هي التجارة مع الله تعالى.\nrefl\nوَمَا يَسۡتَوِي ٱلۡأَحۡيَآءُ وَلَا ٱلۡأَمۡوَٰتُۚ إِنَّ ٱللَّهَ يُسۡمِعُ مَن يَشَآءُۖ وَمَآ أَنتَ بِمُسۡمِعٖ مَّن فِي ٱلۡقُبُورِ ٢٢\nتمثيل لمن آمن؛ فهو كالحي، ومن لم يؤمن؛ فهو كالميت. ﴿إِنَّ ٱللَّهَ يُسۡمِعُ مَن يَشَآءُۖ﴾: عبارة عن هداية الله لمن يشاء. ﴿وَمَآ أَنتَ بِمُسۡمِعٍ مَّن فِي ٱلۡقُبُورِ﴾: عبارة عن عدم سماع الكفار للبراهين والمواعظ، فشبههم بالموتى في عدم إحساسهم. ابن جزي:٢/٢١٥.\nفي هذه الآية تمثيل بليغ بين الكفار والموتى، بيِّن أوجه الشبه في ذلك.\nوَمَا يَسۡتَوِي ٱلۡأَحۡيَآءُ وَلَا ٱلۡأَمۡوَٰتُۚ إِنَّ ٱللَّهَ يُسۡمِعُ مَن يَشَآءُۖ وَمَآ أَنتَ بِمُسۡمِعٖ مَّن فِي ٱلۡقُبُورِ ٢٢\nأعظم حرمان نشأ عن الكفر هو حرمان الانتفاع بأبلغ كلام وأصدقه؛ وهو القرآن. ابن عاشور:٢٢/٢٩٥.\nما أعظم حرمان حُرمه الكافر في الدنيا؟\nأَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦ ثَمَرَٰتٖ مُّخۡتَلِفًا أَلۡوَٰنُهَاۚ وَمِنَ ٱلۡجِبَالِ جُدَدُۢ بِيضٞ وَحُمۡرٞ مُّخۡتَلِفٌ أَلۡوَٰنُهَا وَغَرَابِيبُ سُودٞ ٢٧ وَمِنَ ٱلنَّاسِ وَٱلدَّوَآبِّ وَٱلۡأَنۡعَٰمِ مُخۡتَلِفٌ أَلۡوَٰنُهُۥ كَذَٰلِكَۗ\nيذكر تعالى خلقه للأشياء المتضادات التي أصلها واحد، ومادتها واحدة، وفيها من التفاوت والفرق ما هو مشاهد معروف؛ ليدل العباد على كمال قدرته وبديع حكمته... فتفاوتها دليل عقلي على مشيئة الله تعالى التي خصصت ما خصصت منها بلونه ووصفه، وقدرة الله تعالى حيث أوجدها كذلك، وحكمته ورحمته. السعدي:٦٨٨.\nما الصفة الإلهية المستفادة من تعدد الخلق وتشكله وتلونه؟\nإِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْۗ إِنَّ ٱللَّهَ عَزِيزٌ غَفُورٌ ٢٨\nقال الربيع بن أنس: \"من لم يخش الله تعالى فليس بعالم\"، وعن ابن مسعود: \"كفى بخشية الله تعالى علمًا، وبالاغترار به جهلًا\"، وعن مجاهد قال: \"إنَّما الفقيه من يخاف الله -عز وجل-\". القرطبي:١٧/٣٧٥-٣٧٦.\nما الصفة البارزة التي تميز طالب العلم الصادق؟\nإِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْۗ إِنَّ ٱللَّهَ عَزِيزٌ غَفُورٌ ٢٨\nوالمراد بالعلماء: العلماء بالله وبالشريعة. وعلى حسب مقدار العلم في ذلك تقوَى الخشية؛ فأما العلماء بعلوم لا تتعلق بمعرفة الله وثوابه وعقابه معرفة على وجهها؛ فليست علومهم بمقربة لهم من خشية الله. ابن عاشور:٢٢/٣٠٤.\nمن العالم حقًا؟\nإِنَّ ٱلَّذِينَ يَتۡلُونَ كِتَٰبَ ٱللَّهِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ يَرۡجُونَ تِجَٰرَةٗ لَّن تَبُورَ ٢٩\nفي الآية ما يشمل ثواب قُرَّاء القرآن؛ فإنهم يصدق عنهم أنهم من الذين يتلون كتاب الله، ويقيمون الصلاة، ولو لم يصاحبهم التدبر في القرآن؛ فإن للتلاوة حظها من الثواب والتنوّر بأنوار كلام الله. ابن عاشور:٢٢/٢٩٧.\nهل لتالي القرآن أجرٌ ولو لم يصاحبه تدبر؟\nإِنَّ ٱلَّذِينَ يَتۡلُونَ كِتَٰبَ ٱللَّهِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ يَرۡجُونَ تِجَٰرَةٗ لَّن تَبُورَ ٢٩\nوهذا فيه أنهم يخلصون بأعمالهم، وأنهم لا يرجون بها من المقاصد السيئة والنيات الفاسدة شيئًا. السعدي:٦٨٩.\nما المستفاد من قوله تعالى ﴿يَرۡجُونَ تِجَٰرَةً لَّن تَبُورَ﴾؟"],[438,"§فاطر\nwords\nظَالِمٌ لِنَفسِهِبِفِعلِ بَعضِ المَعَاصِي.\nمُقتَصِدٌيُؤَدِّي الوَاجِبَاتِ، ويَجتَنِبُ المُحَرَّمَاتِ.\nسَابِقٌ بِالخَيرَاتِمُجتَهِدٌ فِي عَمَلِ الصَّالِحَاتِ: فَرضِهَا وَنَفلِهَا.\nعَدنٍإِقَامَةٍ.\nلُغُوبٌإِعيَاءٌ وَتَعَبٌ.\ndeeds\nقل: \"اللهم ارزقني حفظ كتابك، والعمل به، والدعوة إليه\".\nسابق جماعة مسجدك على الصف الأول.\nارسل رسالة تذكر فيها أن من أراد لباس أهل الجنة فليبتعد عن اللباس المحرم في الدنيا.\nguid\nلا تعظم نفسك، ولا تستكثر عملك؛ فهذه عائشة -رضي الله عنها- تعد نفسها من الظالمات لأنفسهن.\nاعلم أن من اصطفاه الله تعالى ورثه علم الكتاب، والعمل به؛ فكن منهم.\nتأمل كيف شمل ربنا -جل وعلا- الظالم لنفسه مع عباده المصطفين.\nrefl\nثُمَّ أَوۡرَثۡنَا ٱلۡكِتَٰبَ ٱلَّذِينَ ٱصۡطَفَيۡنَا مِنۡ عِبَادِنَاۖ فَمِنۡهُمۡ ظَالِمٞ لِّنَفۡسِهِۦ وَمِنۡهُم مُّقۡتَصِدٞ وَمِنۡهُمۡ سَابِقُۢ بِٱلۡخَيۡرَٰتِ بِإِذۡنِ ٱللَّهِۚ ذَٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِيرُ ٣٢\nقال عمر وابن مسعود وابن عباس وكعب وعائشة وأكثر المفسرين: هذه الأصناف الثلاثة في أمة محمد -صلى الله عليه وسلم-؛ فالظالم لنفسه: العاصي، والسابق: التقي، والمقتصد: بينهما. ابن جزي:٢/٢١٧.\nإلى أي امّة ينتمي الأصناف الثلاثة المذكورون في الآية؟ مع بيان المراد بصفاتهم.\nوَمِنۡهُم مُّقۡتَصِدٞ وَمِنۡهُمۡ سَابِقُۢ بِٱلۡخَيۡرَٰتِ بِإِذۡنِ ٱللَّهِۚ\nوقوله: ﴿بِإِذۡنِ ٱللَّهِ﴾ راجع إلى السابق بالخيرات؛ لئلَّا يغتر بعمله، بل ما سبق إلى الخيرات إلا بتوفيق الله تعالى ومعونته، فينبغي له أن يشتغل بشكر الله تعالى على ما أنعم به عليه. السعدي:٦٨٩.\nلماذا خص السابق بالخيرات بقوله: ﴿بِإِذۡنِ ٱللَّهِ﴾ ؟\nوَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَذۡهَبَ عَنَّا ٱلۡحَزَنَۖ إِنَّ رَبَّنَا لَغَفُورٞ شَكُورٌ ٣٤\nقال ابن عباس: \"حزن النار\"، وقال قتادة: \"حزن الموت\"، وقال مقاتل: \"حزنوا لأنهم كانوا لا يدرون ما يصنع الله بهم\"، وقال عكرمة: \"حزن الذنوب والسيئات، وخوف رد الطاعات\". البغوي:٣/٦٢٦.\nما الذي أحزن أهل الإيمان في الدنيا فأذهبه الله عنهم في الجنة؟\nٱلَّذِيٓ أَحَلَّنَا دَارَ ٱلۡمُقَامَةِ مِن فَضۡلِهِۦ لَا يَمَسُّنَا فِيهَا نَصَبٞ وَلَا يَمَسُّنَا فِيهَا لُغُوبٞ ٣٥\n﴿دَارَ ٱلۡمُقَامَةِ﴾: هي الجنة، والمقامة: هي الإقامة والموضع، وإنَّما سميت الجنة دار المقامة؛ لأنهم يقومون فيها ولا يخرجون منها. ابن جزي:٢/٢١٧.\nلم سمّيت الجنّة بدار المقامة؟\nٱلَّذِيٓ أَحَلَّنَا دَارَ ٱلۡمُقَامَةِ مِن فَضۡلِهِۦ\nالذي أعطانا هذه المنزلة وهذا المقام من فضله ومنته ورحمته؛ لم تكن أعمالنا تساوي ذلك. ابن كثير:٤/٥٣٥.\nهل يدخل الإنسان الجنة بمجرد عمله؟ وضح ذلك من خلال الآية.\nوَٱلَّذِينَ كَفَرُواْ لَهُمۡ نَارُ جَهَنَّمَ لَا يُقۡضَىٰ عَلَيۡهِمۡ فَيَمُوتُواْ وَلَا يُخَفَّفُ عَنۡهُم مِّنۡ عَذَابِهَاۚ كَذَٰلِكَ نَجۡزِي كُلَّ كَفُورٖ ٣٦\nوقوله: ﴿لَا يُقۡضَىٰ﴾ معناه: لا يجهز؛ لأنهم لو ماتوا لبطلت حواسهم فاستراحوا. ابن عطية:٤/٤٤٠.\nلماذا نفي الموت عن أهل النار؟\nوَهُمۡ يَصۡطَرِخُونَ فِيهَا رَبَّنَآ أَخۡرِجۡنَا نَعۡمَلۡ صَٰلِحًا غَيۡرَ ٱلَّذِي كُنَّا نَعۡمَلُۚ\nقال ابن عباس: \"نقل: لا إله إلا الله\"... أي: نؤمن بدل الكفر، ونطيع بدل المعصية، ونمتثل أمر الرسل. القرطبي:١٧/٣٨٨.\nما العمل الصالح الذي يتمناه أهل النار بعد دخولهم فيها؟"],[439,"§فاطر\nwords\nخَلاَئِفَيَخلُفُ بَعضُكُم بَعضًا فِي الأَرضِ.\nمَقتًابُغضًا وَغَضَبًا.\nأَرَأَيتُمأَخبِرُونِي.\nبَيِّنَةٍ مِنهُحُجَّةٍ مِنهُ.\nغُرُورًاخِدَاعًا وَبَاطِلًا.\nجَهدَ أَيمَانِهِممُجتَهِدِينَ في الحَلِفِ بِأَغلَظِ الأَيمَانِ.\nيَحِيقُيُحِيطُ، وَينزِلُ.\ndeeds\nتواص أنت وزميلك على عمل صالح تقومان به.\nتعبد لله باسمه الحليم الغفور، وقل: يا حليم احلم علي ولا تعذبني، يا غفور اغفر لي وارحمني.\nشاهد فيلمًا وثائقيا، أو صورًا عن براكين أو زلازل أو فيضانات، متأملًا قدرة الله -عز وجل- وضعف البشر.\nguid\nالكفر والمعصية يزيدان العبد عند الله تعالى مقتًا وبغضًا.\nاعلم أن وعود الظالمين بعضهم لبعض غرور وكذب؛ فاحذر الاغترار بهم.\nأبشر ولا تخف؛ فإن المكر السيئ لا يحيق إلا بأهله.\nrefl\nهُوَ ٱلَّذِي جَعَلَكُمۡ خَلَٰٓئِفَ فِي ٱلۡأَرۡضِۚ فَمَن كَفَرَ فَعَلَيۡهِ كُفۡرُهُۥۖ\nيقول تعالى ذكره: فمن كفر بالله منكم أيها الناس؛ فعلى نفسه ضر كفره، لا يضر بذلك غير نفسه؛ لأنه المعاقب عليه دون غيره. الطبري:٢٠/٤٨٠.\nعلى من يقع ضرر كفر ابن آدم؟\nوَلَا يَزِيدُ ٱلۡكَٰفِرِينَ كُفۡرُهُمۡ عِندَ رَبِّهِمۡ إِلَّا مَقۡتٗاۖ\nأي: كلما استمروا على كفرهم أبغضهم الله تعالى... بخلاف المؤمنين؛ فإنهم كلما طال عمر أحدهم وحسن عمله ارتفعت درجته ومنزلته في الجنة، وزاد أجره، وأحبه خالقه وبارئه رب العالمين. ابن كثير:٣/٥٣٨.\nفي الآية ذكر لمَّا يفعله الكفر بالكافرين، فما الذي يفعله الإيمان بالمؤمنين؟\nوَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِن جَآءَهُمۡ نَذِيرٞ لَّيَكُونُنَّ أَهۡدَىٰ مِنۡ إِحۡدَى ٱلۡأُمَمِۖ فَلَمَّا جَآءَهُمۡ نَذِيرٞ مَّا زَادَهُمۡ إِلَّا نُفُورًا ٤٢\nوليس إقسامهم المذكور لقصد حسن، وطلب للحق، وإلا لوفِّقوا له، ولكنه صادر عن استكبار في الأرض على الخلق وعلى الحق، وبهرجة في كلامهم هذا؛ يريدون به المكر والخداع، وأنهم أهل الحق الحريصون على طلبه، فيغتر به المغترون، ويمشي خلفهم المقتدون. السعدي:٦٩١.\nهل كان قسمهم هذا طلبًا للحق؟\nٱسۡتِكۡبَارٗا فِي ٱلۡأَرۡضِ وَمَكۡرَ ٱلسَّيِّيِٕۚ وَلَا يَحِيقُ ٱلۡمَكۡرُ ٱلسَّيِّئُ إِلَّا بِأَهۡلِهِۦۚ\n(استكبارًا): أَي: عُتُوًّا عنِ الإيمانِ، ﴿وَمَكۡرَ ٱلسَّيِّيِٕۚ﴾: أَي: مكر العملِ السيّئ؛ وهو الكُفر وخَدعُ الضُّعَفَاءِ، وَصَدُّهُم عنِ الإيمانِ؛ ليكثر أَتباعهم. القرطبي:١٧/٣٩٦.\nما حقيقة مكرهم السيِّئ الذي أوقعهم في العقوبة لنحذر منه؟\nٱسۡتِكۡبَارٗا فِي ٱلۡأَرۡضِ وَمَكۡرَ ٱلسَّيِّيِٕۚ وَلَا يَحِيقُ ٱلۡمَكۡرُ ٱلسَّيِّئُ إِلَّا بِأَهۡلِهِۦۚ فَهَلۡ يَنظُرُونَ إِلَّا سُنَّتَ ٱلۡأَوَّلِينَۚ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبۡدِيلٗاۖ وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحۡوِيلًا ٤٣\nفإذا لم يأمن أفراد الإنسان بعضهم بعضًا؛ تنكَّر بعضهم لبعض، وتبادروا الإِضرار والإِهلاك؛ ليفوز كل واحد بكيد الآخر قبل أن يَقع فيه؛ فيفضي ذلك إلى فساد كبير في العالم، والله لا يحب الفساد. ابن عاشور:٢٢/٣٣٥.\nما آثار فقد الأمن في المجتمع؟ بين ذلك من خلال الآية.\nفَهَلۡ يَنظُرُونَ إِلَّا سُنَّتَ ٱلۡأَوَّلِينَۚ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبۡدِيلٗاۖ وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحۡوِيلًا ٤٣\nأجرى الله العذاب على الكفار، وجعل ذلك سنة فيهم، فهو يعذب بمثله من استحقه، لا يقدر أحد أن يبدل ذلك، ولا أن يحوّل العذاب عن نفسه إلى غيره. القرطبي:١٧/٤٠٠.\nهل تتبدل سنة الله تعالى في نزول العقوبة على من عصى؟\nوَمَا كَانَ ٱللَّهُ لِيُعۡجِزَهُۥ مِن شَيۡءٖ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ عَلِيمٗا قَدِيرٗا ٤٤\nعجز المريد عن تحقيق إرادته إما أن يكون سببه خفاء موضع تحقق الإِرادة؛ وهذا ينافي إحاطة العلم، أو عدم استطاعة التمكن منه؛ وهذا ينافي عموم القدرة. ابن عاشور:٢٢/٣٣٩.\nما المستفاد من ختم الآية بوصف الله تعالى بصفتي العلم والقدرة؟"],[440,"§يسٓ ، فاطر\nwords\nفِي أَعنَاقِهِم أَغلاَلًاجُمِعَت أَيدِيهِم إِلَى أَعنَاقِهِم؛ تَمثِيلٌ لِشِدَّةِ إِعرَاضِهِم.\nمُقمَحُونَرَافِعُونَ رُؤُوسَهُم، لاَ يَستَطِيعُونَ خَفضَهَا.\nفَأَغشَينَاهُمأَعمَينَا أَبصَارَهُم.\nوَآثَارَهُممَا سَنُّوهُ، وَأَبقَوهُ مِن خَيرٍ وَشَرٍّ.\ndeeds\nتذكر موعظة سمعتها واتبع ماجاء فيها من وصايا حتى تبشر بمغفرة وأجر كريم.\nاختر عملًا يبقى أثره بعد موتك، واعمل به اليوم؛ كالمساعدة في بناء مسجد، أو دعوة غير مسلم إلى الإسلام، أو تعليم جاهلٍ شيئًا، أو نحو ذلك.\nاذهب إلى المسجد ماشيًا؛ تكتب لك خطواتك.\nguid\nتيقن أن من حان أجله فلن يتأخر عنه لحظة واحدة.\nمن حق عليه العذاب فلا تنفع فيه النذارة.\nإذا خشيت من ظلم ظالم فقل.\nrefl\nوَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُواْ مَا تَرَكَ عَلَىٰ ظَهۡرِهَا مِن دَآبَّةٖ\nقال ابن مسعود: \"كاد الجُعل أن يُعذب في جحره بذنب ابن آدم\". وقال يحيى بن أبي كثير: أمر رجل بالمعروف ونهى عن المنكر، فقال له رجل: عليك بنفسك؛ فإن الظالم لا يضر إلا نفسه، فقال أبو هريرة: \"كذبت -والله الذي لا إله إلا هو-\"، ثم قال: \"والذي نفسي بيده، إن الحبارى لتموت هزلًا في وكرها بظلم الظالم\". القرطبي:١٧/٤٠١-٤٠٢.\nهل يصل أثر ذنوب العباد إلى الدواب والبهائم؟\nوَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُواْ مَا تَرَكَ عَلَىٰ ظَهۡرِهَا مِن دَآبَّةٖ وَلَٰكِن يُؤَخِّرُهُمۡ إِلَىٰٓ أَجَلٖ مُّسَمّٗىۖ فَإِذَا جَآءَ أَجَلُهُمۡ فَإِنَّ ٱللَّهَ كَانَ بِعِبَادِهِۦ بَصِيرَۢا ٤٥\nتذكير لهم عن أن يغرهم تأخير المؤاخذة؛ فيحسبوه عجزًا، أو رضى من الله بما هم فيه؛ فهم الذين قالوا: ﴿وَإِذۡ قَالُواْ ٱللَّهُمَّ إِن كَانَ هَٰذَا هُوَ ٱلۡحَقَّ مِنۡ عِندِكَ فَأَمۡطِرۡ عَلَيۡنَا حِجَارَةٗ مِّنَ ٱلسَّمَآءِ أَوِ ٱئۡتِنَا بِعَذَابٍ أَلِيمٖ﴾ [الأنفال: ٣٢]؛ فعلَّمهم أن لعذاب الله آجالًا اقتضتها حِكمتهُ، فيها رَعي مصالح أمم آخرين، أو استبقاءُ أجيال آتين. ابن عاشور:٢٢/٣٣٩.\nتأخر عقوبة المشرك ليس علامة على صحة حاله، كيف وضحت الآية الكريمة ذلك؟\nوَٱلۡقُرۡءَانِ ٱلۡحَكِيمِ ٢ إِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ ٣\nالقرآن العظيم أقوى الأدلة المتصلة المستمرة على رسالة الرسول؛ فأدلة القرآن كلها أدلة لرسالة محمد -صلى الله عليه وسلم-. السعدي:٦٩٢.\nما أقوى أدلة رسالة النبي -صلى الله عليه وسلم- ؟\nتَنزِيلَ ٱلۡعَزِيزِ ٱلرَّحِيمِ ٥\nفحماه بعزته عن التغيير والتبديل، ورحم به عباده رحمة اتصلت بهم حتى أوصلتهم إلى دار رحمته؛ ولهذا ختم الآية بهذين الاسمين الكريمين: ﴿ٱلۡعَزِيزُ ٱلرَّحِيمُ﴾. السعدي:٦٩٢.\nلماذا ختمت الآية بهذين الاسمين الكريمين: ﴿ٱلۡعَزِيزُ ٱلرَّحِيمُ﴾؟\nإِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكۡرَ وَخَشِيَ ٱلرَّحۡمَٰنَ بِٱلۡغَيۡبِۖ فَبَشِّرۡهُ بِمَغۡفِرَةٖ وَأَجۡرٖ كَرِيمٍ ١١\nوالتعبير بوصف (الرحمن) دون اسم الجلالة لوجهين؛ أحدهما: أن المشركين كانوا ينكرون اسم الرحمن؛ كما قال تعالى: ﴿قَالُواْ وَمَا ٱلرَّحۡمَٰنُ﴾ [الفرقان: ٦٠]. والثاني: الإِشارة إلى أن رحمته لا تقتضي عدم خشيته؛ فالمؤمن يخشى الله مع علمه برحمته؛ فهو يرجو الرحمة. ابن عاشور:٢٢/٣٥٤.\nلماذا جاء وصف (الرَّحمن) دون اسم الجلالة (الله) تعالى في الآية الكريمة؟\nإِنَّا نَحۡنُ نُحۡيِ ٱلۡمَوۡتَىٰ وَنَكۡتُبُ مَا قَدَّمُواْ وَءَاثَٰرَهُمۡۚ وَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ فِيٓ إِمَامٖ مُّبِينٖ ١٢\nفآثار المرء التي تبقى وتذكر بعد الإنسان من خير أو شر يجازى عليها: من أثر حسن؛ كعلم علموه، أو كتاب صنفوه... أو سيئ؛ كوظيفة وظفها بعض الظلام من المسلمين... أو شيء أحدثه فيه صد عن ذكر الله من ألحان وملاهٍ. وكذلك كل سنة حسنة أو سيئة يستن بها. القرطبي:١٧/٤٢٠.\nما أهمية تركك لأثر حسن بعد وفاتك؟ وما عاقبة ترك الأثر السيئ؟\nإِنَّا نَحۡنُ نُحۡيِ ٱلۡمَوۡتَىٰ وَنَكۡتُبُ مَا قَدَّمُواْ وَءَاثَٰرَهُمۡۚ\nوهي آثار الخير وآثار الشر التي كانوا هم السبب في إيجادها في حال حياتهم وبعد وفاتهم... وهذا الموضع يبين لك علو مرتبة الدعوة إلى الله، والهداية إلى سبيله بكل وسيلة وطريق موصل إلى ذلك، ونزول درجة الداعي إلى الشر الإمام فيه، وأنه أسفل الخليقة وأشدهم جرمًا وأعظمهم إثمًا. السعدي:٦٩٣.\nبَيِّن مرتبة الدعوة إلى الله من خلال هذه الآية."],[441,"§يسٓ\nwords\nفَعَزَّزنَاأَيَّدنَا، وَقَوَّينَا.\nتَطَيَّرنَا بِكُمتَشَاءَمنَا بِكُم.\nطَائِرُكُم مَعَكُمشُؤمُكُم، وَأَعمَالُكُم مِنَ الشِّركِ وَالشَّرِّ مَعَكُم، وَمَردُودَةٌ عَلَيكُم.\nأَئِن ذُكِّرتُمأَئِن وُعِظتُم تَشَاءَمتُم؟!\nيَسعَىيُسرِعُ فِي مَشيِهِ.\nفَطَرَنِيخَلَقَنِي.\ndeeds\nاذهب إلى مجموعة من الغافلين عن الصلاة، وانصحهم بأدائها.\nانصر أحد الصالحين أو الدعاة وبين فضله وسيرته، وانشرها برسالة أو بأي وسيلة أخرى.\nأعذر إلى الله بإبلاغ حق، أو بإنكار منكر.\nguid\nاتبع الرسل، واقتف أثرهم.\nلا تسأل أجرًا على دعوتك؛ فهذا من أسباب القبول.\nكن محبًا لهداية الناس لا لعذابهم، فذلك من أعظم ما يتخلق به الداعية الرباني.\nrefl\nوَٱضۡرِبۡ لَهُم مَّثَلًا أَصۡحَٰبَ ٱلۡقَرۡيَةِ\nتعيين تلك القرية لو كان فيه فائدة لَعَيَّنَهَا الله... ما تعرف به أن طريق العلم الصحيح الوقوف مع الحقائق، وترك التعرض لما لا فائدة فيه، وبذلك تزكو النفس، ويزيد العلم من حيث يظن الجاهل أن زيادته بذكر الأقوال التي لا دليل عليها ولا حجة عليها ولا يحصل منها من الفائدة إلا تشويش الذهن واعتياد الأمور المشكوك فيها. السعدي:٦٩٣.\nما الطريقة المثلى للتعامل مع المبهمات في القرآن؟ ولماذا؟\nقَالُواْ طَٰٓئِرُكُم مَّعَكُمۡ أَئِن ذُكِّرۡتُمۚ بَلۡ أَنتُمۡ قَوۡمٞ مُّسۡرِفُونَ ١٩\nوقولهم -عليهم السلام-: ﴿طَٰٓئِرُكُم مَّعَكُمۡ﴾ معناه: حظكم وما صار إليه من خير وشر معكم؛ أي: من أفعالكم ومن تكسباتكم، ليس هو من أجلنا ولا بسببنا، بل ببغيكم وكفركم؛ وبهذا فسر الناس. وسمي الحظ والنصيب طائرًا استعارة؛ أي: هو مما تحصل عن النظر في الطائر. ابن عطية:٤/٤٥٠.\nفي الآية رد على من يرى التطير بشيء والتشاؤم منه، وضح ذلك.\nوَجَآءَ مِنۡ أَقۡصَا ٱلۡمَدِينَةِ رَجُلٞ يَسۡعَىٰ قَالَ يَٰقَوۡمِ ٱتَّبِعُواْ ٱلۡمُرۡسَلِينَ ٢٠\nووصفُ الرجل بالسعي يفيد أنه جاء مسرعًا، وأنه بلغه همُّ أهل المدينة برجم الرسل أو تعذيبهم، فأراد أن ينصحهم خشيةً عليهم وعلى الرسل، وهذا ثناء على هذا الرجل يفيد أنه ممن يُقتدَى به في الإِسراع إلى تغيير المنكر. ابن عاشور:٢٢/٣٦٦.\nما فائدة الوصف بالجملة الفعلية: (يسعى) في الآية الكريمة؟\nوَجَآءَ مِنۡ أَقۡصَا ٱلۡمَدِينَةِ رَجُلٞ يَسۡعَىٰ قَالَ يَٰقَوۡمِ ٱتَّبِعُواْ ٱلۡمُرۡسَلِينَ ٢٠\nوبهذا يظهر وجه تقديم (من أقصى المدينة) على (رجل) للاهتمام بالثناء على أهل أقصى المدينة، وأنه قد يوجد الخير في الأطراف ما لا يوجد في الوسط، وأن الإِيمان يسبق إليه الضعفاء؛ لأنهم لا يصدهم عن الحق ما فيه أهل السيادة من ترف وعظمة؛ إذ المعتاد أنهم يسكنون وسط المدينة. ابن عاشور:٢٢/٣٦٥.\nلماذا قُدِّم لفظ (من أقصى المدينة) على (رجل)؟\nٱتَّبِعُواْ مَن لَّا يَسۡـَٔلُكُمۡ أَجۡرٗا وَهُم مُّهۡتَدُونَ ٢١\nأي: هؤلاء المرسلون لا يسألونكم أجرة على الإيمان، فلا تخسرون معهم شيئًا من دنياكم، وتربحون معهم الاهتداء في دينكم. ابن جزي:٢/٢٢٢.\nذكرت الآية عاملَين من عوامل صدق الداعي؛ فما هما؟\nٱتَّبِعُواْ مَن لَّا يَسۡـَٔلُكُمۡ أَجۡرٗا وَهُم مُّهۡتَدُونَ ٢١\n﴿ٱتَّبِعُواْ مَن لَّا يَسۡـَٔلُكُمۡ أَجۡرًا﴾ أي: اتبعوا من نصحكم نصحًا يعود إليكم بالخير، وليس يريد منكم أموالكم، ولا أجرًا على نصحه لكم وإرشاده إياكم؛ فهذا موجب لاتباع من هذا وصفه. بقي أن يقال: فلعله يدعو ولا يأخذ أجرة، ولكنه ليس على الحق؛ فدفع هذا الاحتراز بقوله: ﴿وَهُم مُّهۡتَدُونَ﴾؛ لأنهم لا يدعون إلا لما يشهد العقل الصحيح بحسنه، ولا ينهون إلا بما يشهد العقل الصحيح بقبحه. السعدي:٦٩٤.\nلماذا ختمت الآية بقوله سبحانه: ﴿وَهُم مُّهۡتَدُونَ﴾؟\nقِيلَ ٱدۡخُلِ ٱلۡجَنَّةَۖ قَالَ يَٰلَيۡتَ قَوۡمِي يَعۡلَمُونَ ٢٦ بِمَا غَفَرَ لِي رَبِّي وَجَعَلَنِي مِنَ ٱلۡمُكۡرَمِينَ ٢٧\nوفي هذه الآية تنبيه عظيم، ودلالة على وجوب كظم الغيظ، والحلم عن أهل الجهل، والترؤف على من أدخل نفسه في غمار الأشرار وأهل البغي، والتشمر في تخليصه، والتلطف في افتدائه، والاشتغال بذلك عن الشماتة به والدعاء عليه، ألا ترى كيف تمنى الخير لقتلته والباغين له الغوائل، وهم كفرة عبدة أصنام. القرطبي:١٧/٤٣٣.\nما الخلق العظيم الذي يتعلمه المؤمن من هذه الآية؟"],[442,"§يسٓ\nwords\nخَامِدُونَمَيِّتُونَ، هَامِدُونَ.\nمُحضَرُونَنُحضِرُهُم لِلجَزَاءِ وَالحِسَابِ.\nنَسلَخُنَنزِعُ.\nكَالعُرجُونِ القَدِيمِمِثلَ عِذقِ النَّخلَةِ المُتَقَوِّسِ فِي الرِّقَّةِ، وَالاِنحِنَاءِ، وَالصُّفرَةِ؛ لِقِدَمِهِ.\nيَسبَحُونَيَجرُونَ.\ndeeds\nاقرأ في القرآن قصة من قصص الأنبياء وتأمل ما حل بأقوامهم؛ كقوم فرعون، أو عادٍ، أو غيرهم.\nتأمل بعض الحبوب أو الثمار في طعامك مِن بذرها حتى وصولها إليك، ثم اشكر الله على نعمه التي لا تحصى.\nقل في الصباح: \"اللهم بك أصبحنا وبك أمسينا، وبك نحيا وبك نموت، وإليك النشور\"، وفي المساء: \"اللهم بك أمسينا وبك أصبحنا، وبك نحيا وبك نموت، إليك المصير\".\nguid\nبيان شدة عقوبة الله تعالى لمن عصاه؛ حيث أهلكهم بصيحة واحدة.\nتذكر مثول الخلائق كلها بين يدي الله تعالى.\nتفكر في مخلوقات الله تعالى، في الأرض وثمارها، وفي السماء وكواكبها.\nrefl\n۞وَمَآ أَنزَلۡنَا عَلَىٰ قَوۡمِهِۦ مِنۢ بَعۡدِهِۦ مِن جُندٖ مِّنَ ٱلسَّمَآءِ وَمَا كُنَّا مُنزِلِينَ ٢٨\nالمعنى أن الله أهلكهم بصيحة صاحها جبريل، ولم يحتج في تعذيبهم إلى إنزال جند من السماء؛ لأنهم أهون من ذلك. ابن جزي:٢/٢٢٣.\nمن خلال الآية بين ضعف القرى وهوانها على الله إذا أراد عذابها.\n۞وَمَآ أَنزَلۡنَا عَلَىٰ قَوۡمِهِۦ مِنۢ بَعۡدِهِۦ مِن جُندٖ مِّنَ ٱلسَّمَآءِ وَمَا كُنَّا مُنزِلِينَ ٢٨\nأي: ما احتجنا أن نتكلف في عقوبتهم فننزل جندًا من السماء لإتلافهم، ﴿وَمَا كُنَّا مُنزِلِينَ﴾؛ لعدم الحاجة إلى ذلك، وعظمة اقتدار الله تعالى، وشدة ضعف بني آدم، وأنهم أدنى شيء يصيبهم من عذاب الله يكفيهم. السعدي:٦٩٥.\nتحدث عن ضعف الجنس البشري من خلال هذه الآية.\nيَٰحَسۡرَةً عَلَى ٱلۡعِبَادِۚ مَا يَأۡتِيهِم مِّن رَّسُولٍ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ٣٠\nيا حسرة من العباد على أنفسهم، وتندمًا وتلهفًا في استهزائهم برسل الله -عليهم السلام-. القرطبي:١٧/٤٣٦.\nما سبب وقوع الحسرة من العباد؟\nوَءَايَةٞ لَّهُمُ ٱلۡأَرۡضُ ٱلۡمَيۡتَةُ أَحۡيَيۡنَٰهَا وَأَخۡرَجۡنَا مِنۡهَا حَبّٗا فَمِنۡهُ يَأۡكُلُونَ ٣٣\nنبههم الله تعالى بهذا على إحياء الموتى، وذكرهم توحيده وكمال قدرته. وهي الأرض الميتة؛ أحياها بالنبات وإخراج الحب منها. القرطبي:١٧/٤٤٠.\nما الفائدة من ذكر الأرض الميتة وإحيائها في هذا الموضع؟\nسُبۡحَٰنَ ٱلَّذِي خَلَقَ ٱلۡأَزۡوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ وَمِنۡ أَنفُسِهِمۡ وَمِمَّا لَا يَعۡلَمُونَ ٣٦\nأي: عجبًا لهؤلاء في كفرهم مع ما يشاهدونه من هذه الآيات، ومن تعجب من شيء قال: سبحان الله. القرطبي:١٧/٤٤١.\nماذا يقول الإنسان عند التعجب من شيء؟\nوَءَايَةٞ لَّهُمُ ٱلَّيۡلُ نَسۡلَخُ مِنۡهُ ٱلنَّهَارَ فَإِذَا هُم مُّظۡلِمُونَ ٣٧ وَٱلشَّمۡسُ تَجۡرِي لِمُسۡتَقَرّٖ لَّهَاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ ٣٨ وَٱلۡقَمَرَ قَدَّرۡنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلۡعُرۡجُونِ ٱلۡقَدِيمِ ٣٩ لَا ٱلشَّمۡسُ يَنۢبَغِي لَهَآ أَن تُدۡرِكَ ٱلۡقَمَرَ وَلَا ٱلَّيۡلُ سَابِقُ ٱلنَّهَارِۚ وَكُلّٞ فِي فَلَكٖ يَسۡبَحُونَ ٤٠\nفكل هذا دليل ظاهر، وبرهان باهر على عظمة الخالق، وعظمة أوصافه، خصوصًا وصف القدرة والحكمة والعلم في هذا الموضع. السعدي:٦٩٦.\nما أبرز الصفات الإلهية التي تدل عليها هذه الآيات المذكورة؟\nوَٱلشَّمۡسُ تَجۡرِي لِمُسۡتَقَرّٖ لَّهَاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ ٣٨\nوذكر صفتي ﴿ٱلۡعَزِيزِ ٱلۡعَلِيمِ﴾ لمناسبة معناهما للتعلق بنظام سير الكواكب؛ فالعزة تناسب تسخير هذا الكوكب العظيم، والعلم يناسب النظام البديع الدقيق. ابن عاشور:٢٣/٢١.\nما مناسبة ختم الآية الكريمة بصفتي ﴿ٱلۡعَزِيزِ ٱلۡعَلِيمِ﴾؟"],[443,"§يسٓ\nwords\nفَلاَ صَرِيخَفَلاَ مُغِيثَ.\nيَخِصِّمُونَيَختَصِمُونَ فِي شُؤُونِ حَيَاتِهِم.\nالأَجدَاثِالقُبُورِ.\nيَنسِلُونَيُسرِعُونَ فِي الخُرُوجِ.\nمَرقَدِنَاقُبُورِنَا.\ndeeds\nتأمل لو لم توجد وسائل النقل الحديثة كيف ستكون معاناتك، ثم اشكر الله تعالى على تسخيرها لنا.\nسل الله، وألِحَّ عليه بقولك: \"اللهم إني أعوذ برضاك من سخطك، وبمعافاتك من عقوبتك\".\nتصدق بجزء من مالك على أحد الفقراء أو المساكين.\nguid\nمن ضعف البشرية أنها احتاجت إلى سفينة واحدة لبقاء نسلها في زمن نوح -عليه السلام-.\nلا ينجي العبد من العذاب الدنيوي والأخروي إلا رحمة الله تعالى.\nإذا سمعت الآية والموعظة فأقبل عليها بقلبك، واعمل بما فيها.\nrefl\nوَءَايَةٞ لَّهُمۡ أَنَّا حَمَلۡنَا ذُرِّيَّتَهُمۡ فِي ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ٤١\nوذكر الذرية لضعفهم عن السفر، فالنعمة فيهم أمكن. ابن عطية:٤/٤٥٥.\nما وجه ذكر الذرية في الآية؟\nمَا يَنظُرُونَ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ تَأۡخُذُهُمۡ وَهُمۡ يَخِصِّمُونَ ٤٩\n﴿وَهُمۡ يَخِصِّمُونَ﴾ أي: وهم لاهون عنها، لم تخطر على قلوبهم في حال خصومتهم وتشاجرهم بينهم، الذي لا يوجد في الغالب إلا وقت الغفلة. السعدي:٦٩٧.\nلماذا خُصَّ وقت التخاصم دون سائر الأوقات؟\nمَا يَنظُرُونَ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ تَأۡخُذُهُمۡ وَهُمۡ يَخِصِّمُونَ ٤٩\nيعني: يختصمون في أمر الدنيا من البيع والشراء، ويتكلمون في المجالس والأسواق. البغوي:٣/٦٤٣.\nبيّن حال غفلة العباد الذين تقوم فيهم القيامة.\nفَلَا يَسۡتَطِيعُونَ تَوۡصِيَةٗ وَلَآ إِلَىٰٓ أَهۡلِهِمۡ يَرۡجِعُونَ ٥٠\nوخص الأهل بالذكر؛ لأن القول معهم في ذلك الوقت أهم على الإنسان من الأجنبيين، وأوكد في نفوس البشر. ابن عطية:٤/٤٥٧.\nخص الأهل بالذكر لوجه فما هو؟\nقَالُواْ يَٰوَيۡلَنَا مَنۢ بَعَثَنَا مِن مَّرۡقَدِنَاۜ هَٰذَا مَا وَعَدَ ٱلرَّحۡمَٰنُ وَصَدَقَ ٱلۡمُرۡسَلُونَ ٥٢\nوقيل: إن الكفار لمَّا قال بعضهم لبعض: ﴿مَنۢ بَعَثَنَا مِن مَّرۡقَدِنَاۜۗ﴾ صدقوا الرسل لمَّا عاينوا ما أخبروهم به، ثم قالوا: ﴿هَٰذَا مَا وَعَدَ ٱلرَّحۡمَٰنُ وَصَدَقَ ٱلۡمُرۡسَلُونَ﴾ فكذبنا به؛ أقروا حين لم ينفعهم الإقرار. القرطبي:١٧/٤٦٥.\nمتى يظهر ندم الكفار على عدم الإيمان والتوبة؟\nقَالُواْ يَٰوَيۡلَنَا مَنۢ بَعَثَنَا مِن مَّرۡقَدِنَاۜ\nيعنون: قبورهم التي كانوا يعتقدون في الدار الدنيا أنهم لا يبعثون منها، فلما عاينوا ما كذبوا به في محشرهم قالوا: (يا ويلنا من بعثنا من مرقدنا)، وهذا لا ينفي عذابهم في قبورهم؛ لأنه بالنسبة إلى ما بعده في الشدة كالرقاد. ابن كثير:٣/٥٥٢.\nهل قول المشركين: ﴿مَنۢ بَعَثَنَا مِن مَّرۡقَدِنَاۜۗ﴾ ينافـي عذاب القبر؟\nهَٰذَا مَا وَعَدَ ٱلرَّحۡمَٰنُ وَصَدَقَ ٱلۡمُرۡسَلُونَ ٥٢\nولا تحسب أن ذكر الرحمن في هذا الموضع لمجرد الخبر عن وعده، وإنَّما ذلك للإخبار بأنه في ذلك اليوم العظيم سيرون من رحمته ما لا يخطر على الظنون، ولا حسب به الحاسبون، كقوله: ﴿ٱلۡمُلۡكُ يَوۡمَئِذٍ ٱلۡحَقُّ لِلرَّحۡمَٰنِ﴾ [الفرقان: ٢٦]، ﴿وَخَشَعَتِ ٱلۡأَصۡوَاتُ لِلرَّحۡمَٰنِ﴾ [طه: ١٠٨]، ونحو ذلك مما يذكر اسمه الرحمن في هذا. السعدي:٦٩٧.\nلماذا خُصَّ اسم الرحمن دون سائر الأسماء في هذا الموقف؟"],[444,"§يسٓ\nwords\nالأَرَائِكِالأَسِرَّةِ المُزَيَّنَةِ.\nوَامتَازُواتَمَيَّزُوا وَانفَصِلُوا عَنِ المُؤمِنِينَ.\nلَمَسَخنَاهُملَغَيَّرنَا خَلقَهُم.\nمَكَانَتِهِمأَمَاكِنِهِم.\nمُضِيًّاأَن يَمضُوا أَمَامَهُم.\nنُعَمِّرهُنُطِل عُمُرَهُ.\nنُنَكِّسهُ فِي الخَلقِنُعِدهُ إِلَى الحَالَةِ الَّتِي ابتَدَأَهَا؛ وَهِيَ الضَّعفُ.\ndeeds\nقل: \"اللهم إني أسألك نعيما لا ينفدُ\".\nاعمل عملًا صالحًا بجوارحك؛ كمساعدة مسلم، أو إماطة أذى عن الطريق، أو مشيٍ إلى صلاة، أو نحو ذلك.\nقل: \"اللهم إني أعوذ بك أن أرد إلى أرذل العمر، أو أن يتخبطني الشيطان عند الموت\".\nguid\nانشغال أهل الجنة بالنعيم، مقابل انشغالهم بالطاعات في الدنيا.\nتدبر، ورتل آيات من كتاب الله تعالى؛ ففيه حياة القلوب.\nلا تكثر من الشعر ونحوه؛ كالأناشيد، حتى لا يصرفك عن القرآن الكريم.\nrefl\nإِنَّ أَصۡحَٰبَ ٱلۡجَنَّةِ ٱلۡيَوۡمَ فِي شُغُلٖ فَٰكِهُونَ ٥٥\nهذا يؤذن بأن أهل الجنة عُجِّل بهم إلى النعيم قبل أن يُبعَث إلى النار أهلُها، وأن أهل الجنة غير حاضرين ذلك المحضر. ابن عاشور:٢٣/٤١.\nمن إكرام الله تعالى لأهل الجنة التعجيل بهم إليها. كيف دلت الآية الكريمة على ذلك؟\nوَٱمۡتَٰزُواْ ٱلۡيَوۡمَ أَيُّهَا ٱلۡمُجۡرِمُونَ ٥٩\nقال مقاتل: \"اعتزلوا اليوم من الصالحين\"... وقال الضحاك: \"إن لكل كافر في النار بيتًا؛ يدخل ذلك البيت ويردم بابه بالنار، فيكون فيه أبد الآبدين\". البغوي:٣/٦٤٥.\nكيف يمتاز المجرمون عن أهل الإيمان يوم القيامة؟\n۞أَلَمۡ أَعۡهَدۡ إِلَيۡكُمۡ يَٰبَنِيٓ ءَادَمَ أَن لَّا تَعۡبُدُواْ ٱلشَّيۡطَٰنَۖ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ ٦٠\nوهذا التوبيخ يدخل فيه التوبيخ عن جميع أنواع الكفر والمعاصي؛ لأنها كلها طاعة للشيطان وعبادة له. السعدي:٦٩٨.\nمن الذي يدخل في هذا التوبيخ المذكور في هذه الآية؟\nٱلۡيَوۡمَ نَخۡتِمُ عَلَىٰٓ أَفۡوَٰهِهِمۡ وَتُكَلِّمُنَآ أَيۡدِيهِمۡ وَتَشۡهَدُ أَرۡجُلُهُم بِمَا كَانُواْ يَكۡسِبُونَ ٦٥\nقيل: لأن اليد مباشرة لعمله، والرجل حاضرة، وقول الحاضر على غيره شهادة، وقول الفاعل على نفسه إقرار بما قال أو فعل؛ فلذلك عبر عما صدر من الأيدي بالقول، وعما صدر من الأرجل بالشهادة. القرطبي:١٧/٤٧٦.\nما سر التعبير بالكلام في حق الأيدي، والشهادة في حق الأرجل؟\nوَمَن نُّعَمِّرۡهُ نُنَكِّسۡهُ فِي ٱلۡخَلۡقِۚ\nيخبر تعالى عن ابن آدم أنه كلما طال عمره رد إلى الضعف بعد القوة، والعجز بعد النشاط... والمراد من هذا -والله أعلم- الإخبار عن هذه الدار بأنها دار زوال وانتقال، لا دار دوام واستقرار. ابن كثير:٣/٥٥٥.\nما المراد من الإخبار عن تنكيس الإنسان عند كِبَرِه؟\nوَمَا عَلَّمۡنَٰهُ ٱلشِّعۡرَ وَمَا يَنۢبَغِي لَهُۥٓۚ إِنۡ هُوَ إِلَّا ذِكۡرٞ وَقُرۡءَانٞ مُّبِينٞ ٦٩\nروى ابن القاسم عن مالك أنه سئل عن إنشاد الشعر فقال: \"لا تكثرن منه، فمن عيبه أن الله يقول: ﴿وَمَا عَلَّمۡنَٰهُ ٱلشِّعۡرَ وَمَا يَنۢبَغِي لَهُۥٓۚ﴾\". القرطبي:١٧/٤٨٤.\nهل الإكثار من الشعر محمود؟ وما دليل ذلك؟\nلِّيُنذِرَ مَن كَانَ حَيّٗا وَيَحِقَّ ٱلۡقَوۡلُ عَلَى ٱلۡكَٰفِرِينَ ٧٠\nلينذر القرآن ﴿مَن كَانَ حَيًّا﴾ يعني: مؤمنًا، حي القلب؛ لأن الكافر كالميت في أنه لا يتدبر ولا يتفكر. البغوي:٣/٦٤٩.\nمن المقصود بالحي والميت في هذه الآية؟"],[445,"§يسٓ\nwords\nوَذَلَّلنَاهَاسَخَّرنَاهَا.\nرَكُوبُهُممَا يَركَبُونَهُ فِي الأَسفَارِ.\nخَصِيمٌكَثِيرُ الخِصَامِ.\nرَمِيمٌبَالِيَةٌ، مُتَفَتِّتَةٌ.\ndeeds\nاشكر الله تعالى على نعمة المركب والمأكل والمشرب والملبس.\nقل: اللهم لا تكلني إلى نفسي طرفة عين، ولا أقل من ذلك\".\nقل: \"اللهم أعني ولا تعن علي، وانصرني ولا تنصر علي، واهدني ويسر الهدى لي\".\nguid\nليكن التجاؤك إلى الله وحده في جميع حاجاتك.\nتأمل أصل خلقتك؛ لتعرف حدود قدرتك.\nلا تجادل، ولا تخاصم على سبيل التعنت ورد الحق.\nrefl\nأَوَ لَمۡ يَرَوۡاْ أَنَّا خَلَقۡنَا لَهُم مِّمَّا عَمِلَتۡ أَيۡدِينَآ أَنۡعَٰمٗا فَهُمۡ لَهَا مَٰلِكُونَ ٧١\nأي: ضابطون قاهرون، أي: لم يخلق الأنعام وحشية نافرة من بني آدم لا يقدرون على ضبطها، بل هي مسخرة لهم. البغوي:٣/٦٤٩.\nما وجه الإنعام بتمليك الأنعام وتذليلها للعباد؟\nوَلَهُمۡ فِيهَا مَنَٰفِعُ وَمَشَارِبُۚ أَفَلَا يَشۡكُرُونَ ٧٣\nفرع على هذا التذكير والامتنان قوله: ﴿أَفَلَا يَشۡكُرُونَ﴾ استفهامًا تعجيبيًا؛ لتركهم تكرير الشكر على هذه النعم العِدّة، فلذلك جيء بالمضارع المفيد للتجديد والاستمرار؛ لأن تلك النعم متتالية متعاقبة في كل حين. ابن عاشور:٢٣/٦٩.\nدلت الآية الكريمة على أهمية تجديد الشكر لله تعالى في كل حين، كيف ذلك؟\nفَلَا يَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّا نَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ ٧٦\nإنا نعلم أن الذي يدعوهم إلى قيل ذلك الحسد، وهم يعلمون أن الذي جئتهم به ليس بشعر، ولا يشبه الشعر، وأنك لست بكذاب. فنعلم ما يسرون؛ من معرفتهم بحقيقة ما تدعوهم إليه، وما يعلنون؛ من جحودهم ذلك بألسنتهم علانية. الطبري:٢٠/٥٥٣.\nما الذي يفيده الداعية من هذه الآية؟\nإِنَّا نَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ ٧٦\nأي: نحن نعلم جميع ما هم فيه، وسنجزيهم وصفهم، ونعاملهم على ذلك؛ يوم لا يفقدون من أعمالهم جليلًا ولا حقيرًا، ولا صغيرًا ولا كبيرًا؛ بل يعرض عليهم جميع ما كانوا يعملون قديمًا وحديثًا. ابن كثير:٣/٥٥٨.\nما المراد من إخبار الله عن نفسه بأنه يعلم ما يسر وما يعلن الكفار؟\nقُلۡ يُحۡيِيهَا ٱلَّذِيٓ أَنشَأَهَآ أَوَّلَ مَرَّةٖۖ وَهُوَ بِكُلِّ خَلۡقٍ عَلِيمٌ ٧٩\nأي: يعلم العظام في سائر أقطار الأرض وأرجائها أين ذهبت، وأين تفرقت وتمزقت. ابن كثير:٣/٥٥٩.\nبيّن سعة علم الله -عز وجل- من خلال الآية.\nٱلَّذِي جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلۡأَخۡضَرِ نَارٗا فَإِذَآ أَنتُم مِّنۡهُ تُوقِدُونَ ٨٠\nثم ذكر دليلًا ثالثًا على البعث: ﴿ٱلَّذِي جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلۡأَخۡضَرِ نَارًا فَإِذَآ أَنتُم مِّنۡهُ تُوقِدُونَ﴾ فإذا أخرج النار اليابسة من الشجر الأخضر الذي هو في غاية الرطوبة، مع تضادهما وشدة تخالفهما، فإخراجه الموتى من قبورهم مثل ذلك. السعدي:٧٠٠.\nما وجه الاستدلال بهذه الآية على البعث؟\nفَسُبۡحَٰنَ ٱلَّذِي بِيَدِهِۦ مَلَكُوتُ كُلِّ شَيۡءٖ وَإِلَيۡهِ تُرۡجَعُونَ ٨٣\nما قدروا الله حق قدره، وكل من أنكر البعث فإنما أنكره لجهله بقدرة الله -سبحانه وتعالى-. ابن جزي:٢/٢٣٠.\nما سبب إنكار الكفار للبعث؟"],[446,"§الصافات\nwords\nوَالصَّآفَّاتِقَسَمٌ بِالمَلاَئِكَةِ حِينَ تَصُفُّ فِي عِبَادَتِهَا.\nفَالزَّاجِرَاتِقَسَمٌ بِالمَلاَئِكَةِ حِينَ تَزجُرُ السَّحَابَ، وَتَسُوقُهُ.\nفَالتَّالِيَاتِ ذِكرًاقَسَمٌ بِالمَلاَئِكَةِ حِينَ تَتلُو ذِكرَ الله، وَكَلاَمَهُ.\nمَارِدٍجِنِّيٍّ مُتَمَرِّدٍ، خَارِجٍ عَنِ الطَّاعَةِ.\nدُحُورًاطَردًا لِلشَّيَاطِينِ عَنِ الاِستِمَاعِ.\nوَاصِبٌدَائِمٌ مُوجِعٌ.\nخَطِفَ الخَطفَةَاختَلَسَ الكَلِمَةَ؛ مُسَارَقَةً بِسُرعَةٍ.\nلاَزِبٍلَزِجٍ يَلتَصِقُ بَعضُهُ بِبَعضٍ.\ndeeds\nتأمل في خلق النجوم، ثم احمد الله على أن منع الشياطين من استراق السمع لئلَّا يفتنوا العباد.\nاستعذ بالله تعالى من شر الشيطان الرجيم.\nتذكر نصيحة سمعتها وبادر بالامتثال لها.\nguid\nتأمل في حال الشياطين ودحرهم بعد بعثة محمد -صلى الله عليه وسلم-.\nلا تكن ممن إذا ذُكِّر لا يتذكر.\nاحفظ لسانك وأفعالك، حتى لا تقف موقفًا يسوؤك بين يدي الله.\nrefl\nوَٱلصَّٰٓفَّٰتِ صَفّٗا ١\nتصف في السماء كصفوف الخلق في الدنيا للصلاة، وقيل: تصف أجنحتها في الهواء واقفة فيه؛ حتى يأمرها الله بما يريد. القرطبي:١٨/٦.\nما حال الملائكة في التذلل والتعبد لله تعالى؟\nإِنَّ إِلَٰهَكُمۡ لَوَٰحِدٞ ٤ رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَرَبُّ ٱلۡمَشَٰرِقِ ٥\nأي: هو الخالق لهذه المخلوقات، والرازق لها، المدبر لها؛ فكما أنه لا شريك له في ربوبيته إياها فكذلك لا شريك له في ألوهيته، وكثيرًا ما يقرر تعالى توحيد الإلهية بتوحيد الربوبية؛ لأنه دالٌّ عليه، وقد أقر به المشركون في العبادة، فيُلزمهم بما أقروا به على ما أنكروه. السعدي:٧٠٠.\nلماذا أتبع الله ذكر الربوبية بعد ذكر الألوهية؟\nإِنَّا زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِزِينَةٍ ٱلۡكَوَاكِبِ ٦\nخص تعالى السماء الدنيا بالذكر؛ لأنها التي تباشر بأبصارنا، وأيضًا فالحفظ من الشيطان إنَّما هو فيه وحدها. ابن عطية:٤/٤٦٦.\nتخصيص ﴿ٱلسَّمَآءَ ٱلدُّنۡيَا﴾ بالذكر هنا لأمرين؛ فما هما؟\nبَلۡ عَجِبۡتَ وَيَسۡخَرُونَ ١٢\nقال قتادة: عجب النبي -صلى الله عليه وسلم- من هذا القرآن حين أنزل وضلال بني آدم، وذلك أن النبي -صلى الله عليه وسلم- كان يظن أن كل من يسمع القرآن يؤمن به، فلما سمع المشركون القرآن؛ سخروا منه ولم يؤمنوا به، فعجب من ذلك. البغوي:٣/٦٥٦\nما الباعث لعجب النبي -صلى الله عليه وسلم- من كفر المشركين بالقرآن؟\nقُلۡ نَعَمۡ وَأَنتُمۡ دَٰخِرُونَ ١٨\nصاغرون أذلاء؛ لأنهم إذا رأوا وقوع ما أنكروه فلا محالة يذلون. القرطبي:١٨/٢٢.\nما سبب ذلة العصاة يوم القيامة؟\n۞ٱحۡشُرُواْ ٱلَّذِينَ ظَلَمُواْ وَأَزۡوَٰجَهُمۡ وَمَا كَانُواْ يَعۡبُدُونَ ٢٢ مِن دُونِ ٱللَّهِ فَٱهۡدُوهُمۡ إِلَىٰ صِرَٰطِ ٱلۡجَحِيمِ ٢٣\nاجمعوهم إلى الموقف؛ للحساب والجزاء. (وأزواجهم): أشباههم وأتباعهم وأمثالهم، قال قتادة والكلبي: \"كل من عمل مثل عملهم؛ فأهل الخمر مع أهل الخمر، وأهل الزنا مع أهل الزنا\". البغوي:٣/٦٥٧.\nمع من يحشر المرء يوم القيامة؟ وماذا نتعلم من ذلك؟\nوَقِفُوهُمۡۖ إِنَّهُم مَّسۡـُٔولُونَ ٢٤\nلما سيقوا إلى النار حبسوا عند الصراط، فقيل: وقفوهم إنهم مسؤولون، قال ابن عباس: عن جميع أقوالهم وأفعالهم. البغوي:٣/٦٥٧.\nأين يكون الوقوف بين يدي الله تعالى؟ وعم يكون السؤال يوم القيامة؟"],[447,"§الصافات\nwords\nعَنِ اليَمِينِمِن قِبَلِ الحَقِّ وَالدِّينِ.\nسُلطَانٍحُجَّةٍ، أَو قُوَّةٍ.\nطَاغِينَمُجَاوِزِينَ الحَدَّ فِي العِصيَانِ.\nفَحَقَّ عَلَينَاوَجَبَ عَلَينَا.\nالمُخلَصِينَالَّذِينَ أَخلَصُوا فِي عِبَادَةِ اللهِ؛ فَأَخلَصَهُم، وَاختَصَّهُم بِرَحمَتِهِ.\nلاَ فِيهَا غَولٌلَيسَ فِيهَا مَا يَغتَالُ عُقُولَهُم.\nوَلاَ هُم عَنهَا يُنزَفُونَلاَ يَسكَرُونَ، وَلاَ تَضُرُّ أَبدَانَهُم.\nمَكنُونٌمحفوظ لَـم تَـمَسَّهُ الأَيدِي.\nقَرِينٌصَاحِبٌ مُلاَزِمٌ لِي.\ndeeds\nزر أخًا لك في الله.\nاكتب رسالة تدافع فيها عن أحد الدعاة.\nأكثر اليوم من قول: \"لا إله إلا الله\".\nguid\nالزم الصالحين من الناس، ودع أراذلهم.\nاحذر المتبوعين المضلين وأهواءهم، فهم ينقلبون في القيامة أعداء.\nتواضع للحق، واخفض له جناحك، ودع الكبر.\nrefl\nمَا لَكُمۡ لَا تَنَاصَرُونَ ٢٥\nفكأنهم لا يجيبون هذا السؤال؛ لأنه قد علاهم الذل والصغار، واستسلموا لعذاب النار، وخشعوا وخضعوا وأبلسوا؛ فلم ينطقوا. السعدي:٧٠٢.\nذكر الله سؤال أهل النار ولم يذكر إجابتهم، فلماذا؟\nفَإِنَّهُمۡ يَوۡمَئِذٖ فِي ٱلۡعَذَابِ مُشۡتَرِكُونَ ٣٣ إِنَّا كَذَٰلِكَ نَفۡعَلُ بِٱلۡمُجۡرِمِينَ ٣٤\nإنا هكذا نفعل بالذين اختاروا معاصي الله في الدنيا على طاعته، والكفر به على الإيمان؛ فنذيقهم العذاب الأليم، ونجمع بينهم وبين قرنائهم في النار. الطبري:٢١/٣٣.\nالاشتراك والتشابه في هذه الدنيا يؤدي إلى الاشتراك في الآخرة، كيف ذلك؟\nأُوْلَٰٓئِكَ لَهُمۡ رِزۡقٞ مَّعۡلُومٞ ٤١ فَوَٰكِهُ وَهُم مُّكۡرَمُونَ ٤٢ فِي جَنَّٰتِ ٱلنَّعِيمِ ٤٣ عَلَىٰ سُرُرٖ مُّتَقَٰبِلِينَ ٤٤ يُطَافُ عَلَيۡهِم بِكَأۡسٖ مِّن مَّعِينِۢ ٤٥ بَيۡضَآءَ لَذَّةٖ لِّلشَّٰرِبِينَ ٤٦ لَا فِيهَا غَوۡلٞ وَلَا هُمۡ عَنۡهَا يُنزَفُونَ ٤٧ وَعِندَهُمۡ قَٰصِرَٰتُ ٱلطَّرۡفِ عِينٞ ٤٨ كَأَنَّهُنَّ بَيۡضٞ مَّكۡنُونٞ ٤٩\nذكر طعامهم وشرابهم ومجالسهم، وعموم النعيم وتفاصيله داخلة في قوله: ﴿فِي جَنَّٰتِ ٱلنَّعِيمِ﴾، لكن فصل هذه الأشياء لتُعلم فتشتاق النفوس إليها. السعدي:٧٠٣.\nلماذا فَصَّل في ذكر نعيم أهل الجنة مع أن قوله: ﴿فِي جَنَّٰتِ ٱلنَّعِيمِ﴾ عام لكل ذلك؟\nفَوَٰكِهُ وَهُم مُّكۡرَمُونَ ٤٢ فِي جَنَّٰتِ ٱلنَّعِيمِ ٤٣\nولهم إكرام من الله -جل وعز- برفع الدرجات، وسماع كلامه ولقائه. القرطبي:١٨/٢٩.\nبيّن شيئًا من إكرام الله تعالى لأهل الجنة.\nلَا فِيهَا غَوۡلٞ وَلَا هُمۡ عَنۡهَا يُنزَفُونَ ٤٧\nأي: لا تغتال عقولهم، ولا يصيبهم منها مرض ولا صداع، وإنَّما صرف الله تعالى السُّكْر عن أهل الجنة؛ لئلَّا ينقطع الالتذاذ عنهم بنعيمهم. القرطبي:١٨/٣١-٣٣.\nلمَ صرف الله السكر عن أهل الجنة؟\nوَعِندَهُمۡ قَٰصِرَٰتُ ٱلطَّرۡفِ عِينٞ ٤٨\nقصرت طرفها على زوجها؛ لعفتها، وعدم مجاوزته لغيره، ولجمال زوجها وكماله؛ بحيث لا تطلب في الجنة سواه، ولا ترغب إلا به... هذا يدل على جمال الرجال في الجنة. السعدي:٧٠٣.\nكيف تدل الآية على كمال جمال الرجال في الجنة؟\nفَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَسَآءَلُونَ ٥٠ قَالَ قَآئِلٞ مِّنۡهُمۡ إِنِّي كَانَ لِي قَرِينٞ ٥١\nمن المعلوم أن لذة أهل العلم بالتساؤل عن العلم والبحث عنه فوق اللذات الجارية في أحاديث الدنيا؛ فلهم من هذا النوع النصيب الوافر، ويحصل لهم من انكشاف الحقائق العلمية في الجنة ما لا يمكن التعبير عنه. السعدي:٧٠٤.\nلأهل العلم نعيمٌ خاصٌّ في الجنة من خلال حديثهم، فما هو؟"],[448,"§الصافات\nwords\nلَمَدِينُونَلَمَجزِيُّونَ، وَمُحَاسَبُونَ.\nإِن كِدتَإِنَّكَ قَارَبتَ.\nلَتُردِينِلَتُهلِكُنِي بِضَلاَلِكَ، وَإِغوَائِكَ.\nالمُحضَرِينَمَن أُحضِرُوا فِي العَذَابِ مَعَكَ.\nطَلعُهَاثَمَرُهَا.\nلَشَوبًالَخَلطًا، وَمِزَاجًا.\nأَلفَواوَجَدُوا.\nيُهرَعُونَيُسرِعُونَ فِي مُتَابَعَتِهِم عَلَى الضَّلاَلِ.\ndeeds\nساعد والدتك في عملها لهذا اليوم.\nصم يومًا تقربًا إلى الله تعالى لتنجو من حر يوم القيامة.\nادع الله تعالى مناديًا، متضرعًا إليه.\nguid\nصديق صالح خير من عشرات الغافلين.\nلا تظلم أحدًا من الناس؛ فشجرة الزقوم عذاب الظالمين.\nاعلم أنه لا مجيب إلا الله، ولا مغيث إلا هو.\nrefl\nفَٱطَّلَعَ فَرَءَاهُ فِي سَوَآءِ ٱلۡجَحِيمِ ٥٥ قَالَ تَٱللَّهِ إِن كِدتَّ لَتُرۡدِينِ ٥٦ وَلَوۡلَا نِعۡمَةُ رَبِّي لَكُنتُ مِنَ ٱلۡمُحۡضَرِينَ ٥٧\nوفي هذه الآية عبرة من الحذر من قرناء السوء، ووجوب الاحتراس مما يدعون إليه، ويزيّنونه من المهالك. ابن عاشور:٢٣/١١٩.\nبيّن خطورة الجليس السيِّئ من الآية الكريمة.\nفَٱطَّلَعَ فَرَءَاهُ فِي سَوَآءِ ٱلۡجَحِيمِ ٥٥\nقال بعض العلماء: لولا أن الله -جل وعز- عرفه إياه لما عرفه، لقد تغير حِبره وسِبره، يعني: لونه وهيئته. القرطبي:١٨/٣٩.\nكيف يعرف القرين قرينه وهو في النار؛ وقد تغير لونه وهيئته؟\nوَلَوۡلَا نِعۡمَةُ رَبِّي لَكُنتُ مِنَ ٱلۡمُحۡضَرِينَ ٥٧\n﴿وَلَوۡلَا نِعۡمَةُ رَبِّي﴾: رحمته وإنعامه علي بالإسلام، ﴿لَكُنتُ مِنَ ٱلۡمُحۡضَرِينَ﴾ معك في النار. البغوي:٣/٦٦١.\nهل نجاة المؤمن من النار وجحيمها بعمله وطاعته فقط؟\nإِنَّهَا شَجَرَةٞ تَخۡرُجُ فِيٓ أَصۡلِ ٱلۡجَحِيمِ ٦٤\nفهذا مخرجها، ومعدنها أشر المعادن وأسوأها، وشر المغرس يدل على شر الغِرَاس وخِسَّتِه، ولهذا نبهنا الله على شرها بما ذكر أين تنبت به، وبما ذكر من صفة ثمرتها. السعدي:٧٠٤.\nما المستفاد من وصف الشجرة بأنها تخرج في أصل الجحيم؟\nطَلۡعُهَا كَأَنَّهُۥ رُءُوسُ ٱلشَّيَٰطِينِ ٦٥\nتبشيع لها، وتكريه لذكرها... وإنَّما شبهها برؤوس الشياطين وإن لم تكن معروفة عند المخاطبين؛ لأنه قد استقر في النفوس أن الشياطين قبيحة المنظر. ابن كثير:٤/١٢.\nكيف شُبِّه طلع شجرة الزقوم بشيء غير معروف وهو رءوس الشياطين؟\nثُمَّ إِنَّ مَرۡجِعَهُمۡ لَإِلَى ٱلۡجَحِيمِ ٦٨ إِنَّهُمۡ أَلۡفَوۡاْ ءَابَآءَهُمۡ ضَآلِّينَ ٦٩\nوكأنه قيل: ما الذي أوصلهم إلى هذه الدار؟ فقال: ﴿إِنَّهُمۡ أَلۡفَوۡاْ ءَابَآءَهُمۡ ضَآلِّينَ﴾. السعدي:٧٠٤.\nما العلاقة بين هاتين الآيتين المتتاليتين؟\nوَلَقَدۡ ضَلَّ قَبۡلَهُمۡ أَكۡثَرُ ٱلۡأَوَّلِينَ ٧١\nووصف الذين ضلّوا قبلهم بأنهم ﴿أَكۡثَرُ ٱلۡأَوَّلِينَ﴾ لئلَّا يَغترّ ضعفاء العقول بكثرة المشركين ولا يعتزّوا بها، ليعلموا أن كثرة العدد لا تبرّر ضلال الضالّين ولا خطأ المخطئين،... فإذا عرضت لإِحداهما كثرة أو قلة؛ فلا تكونان فتنة لقصار الأنظار وضعفاء التفكير؛ قال تعالى: ﴿قُل لَّا يَسۡتَوِي ٱلۡخَبِيثُ وَٱلطَّيِّبُ وَلَوۡ أَعۡجَبَكَ كَثۡرَةُ ٱلۡخَبِيثِ﴾ [المائدة: ١٠٠]. ابن عاشور:٢٣/١٢٨.\nالكثرة والقلة ليسا دالَّين على الهدى أو الضلال؛ بيّن ذلك."],[449,"§الصافات\nwords\nوَتَرَكنَا عَلَيهِأَبقَينَا لَهُ ذِكرًا جَمِيلًا.\nفِي الآخِرِينَفِيمَن جَاءَ بَعدَهُ مِنَ النَّاسِ.\nشِيعَتِهِمَن تَابَعَهُ عَلَى دِينِهِ، وَمِنهَاجِهِ.\nأَئِفكًا آلِهَةًأَتُرِيدُونَ آلِهَةً مُختَلَقَةً تَعبُدُونَهَا؟!\nفَنَظَرَرَفَعَ بَصَرَهُ إِلَى النُّجُومِ مُتَفَكِّرًا فِيمَا يَعتَذِرُ بِهِ مِنَ الخُرُوجِ مَعَهُم.\nسَقِيمٌمَرِيضٌ؛ وَهَذَا تَعرِيضٌ مِنهُ؛ أَرَادَ: أَنِّي لاَ أَخلُو مِن سَقَمٍ كَعَادَةِ النَّاسِ أَو أَنِّي ضَعِيفٌ، أَو سَقِيمُ القَلبِ مِن عِبَادَتِكُم غَيرَ الله.\nيَزِفُّونَيَعدُونَ مُسرِعِينَ غَاضِبِينَ.\ndeeds\nاستعذ بالله من أمراض الشهوات والشبهات.\nقل: \"اللهم ارزقني ذرية صالحة؛ إنك سميع الدعاء\".\nساعد والدك وأجب طلبه على وجه السرعة.\nguid\nكن من المحسنين؛ وذلك بإحسانك عبادة ربك، وبإحسانك إلى الناس.\nطهر قلبك من كل دنس، واسأل الله سلامة قلبك.\nأنكر المنكر بحكمة إذا رأيته، ولو كان من أقرب قريب؛ كالأب ونحوه.\nrefl\nإِذۡ جَآءَ رَبَّهُۥ بِقَلۡبٖ سَلِيمٍ ٨٤\nمخلص من الشرك والشك، وقال عوف الأعرابي: سألت محمد بن سيرين: ما القلب السليم؟ فقال: \"الناصح لله -عز وجل- في خلقه\". القرطبي:١٨/٥٠.\nما سمات القلب السليم لنتصف بها؟\nفَمَا ظَنُّكُم بِرَبِّ ٱلۡعَٰلَمِينَ ٨٧\nفما ظنكم برب العالمين أن يفعل بكم وقد عبدتم معه غيره؟ وهذا ترهيبٌ لهم بالجزاء بالعقاب على الإقامة على شركهم. السعدي:٧٠٥.\nفي الآية تخويفٌ وترهيبٌ للمشركين، بيِّن وجه ذلك.\nفَرَاغَ إِلَىٰٓ ءَالِهَتِهِمۡ فَقَالَ أَلَا تَأۡكُلُونَ ٩١\nإنَّما قال ذلك على وجه الاستهزاء بالذين يعبدون تلك الأصنام. ابن جزي:٢/٢٣٨.\nكيف خاطب إبراهيم -عليه السلام- الأصنام وهي لا تعقل؟\nوَقَالَ إِنِّي ذَاهِبٌ إِلَىٰ رَبِّي سَيَهۡدِينِ ٩٩\nهذه الآية أصل في الهجرة والعزلة، وأول من فعل ذلك إبراهيم -عليه السلام-، وذلك حين خلصه الله من النار؛ قال: ﴿إِنِّي ذَاهِبٌ إِلَىٰ رَبِّي﴾ أي: مهاجر من بلد قومي ومولدي إلى حيث أتمكن من عبادة ربي. القرطبي:١٨/٥٩.\nمتى تشرع العزلة أو الهجرة للمؤمن؟\nرَبِّ هَبۡ لِي مِنَ ٱلصَّٰلِحِينَ ١٠٠\nووصفه بأنه من الصالحين؛ لأن نعمة الولد تكون أكمل إذا كان صالحًا؛ فإن صلاح الأبناء قُرة عين للآباء، ومن صلاحهم برُّهم بوالديهم. ابن عاشور:٢٣/١٤٨.\nبيّن أهمية الدعاء بالولد الصالح.\nفَلَمَّا بَلَغَ مَعَهُ ٱلسَّعۡيَ قَالَ يَٰبُنَيَّ إِنِّيٓ أَرَىٰ فِي ٱلۡمَنَامِ أَنِّيٓ أَذۡبَحُكَ فَٱنظُرۡ مَاذَا تَرَىٰۚ قَالَ يَٰٓأَبَتِ ٱفۡعَلۡ مَا تُؤۡمَرُۖ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ ١٠٢\nإن قيل: لم شاوره في أمر هو حتم من الله؟ فالجواب: أنه لم يشاوره ليرجع إلى رأيه، ولكن ليعلم ما عنده، فيثبت قلبه، ويوطن نفسه على الصبر؛ فأجابه بأحسن جواب. ابن جزي:٢/٢٣٨.\nلم شاور إبراهيم -عليه السلام- ابنه مع أن رؤيا الأنبياء حق؟\nسَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ ١٠٢\nأخبر أباه أنه مُوَطِّنٌ نفسه على الصبر، وقرن ذلك بمشيئة الله تعالى؛ لأنه لا يكون شيء بدون مشيئة الله تعالى. السعدي:٧٠٦.\nما فائدة قرن إسماعيل صبره بمشيئة الله تعالى؟"],[450,"§الصافات\nwords\nأَسلَمَااستَسلَمَا لأِمرِ اللهِ.\nوَتَلَّهُ لِلجَبِينِأَلقَاهُ عَلَى جَانِبِ جَبهَتِهِ عَلَى الأَرضِ.\nالبَلاَءُ المُبِينُالاِختِبَارُ الشَّاقُّ الَّذِي أَبَانَ عَن صِدقِ إِيمَانِهِ.\nوَفَدَينَاهُجَعَلنَا بَدِيلًا عَنهُ.\nبِذِبحٍبِكَبشٍ.\nأَتَدعُونَ بَعلًاأَتَعبُدُونَ الصَّنَمَ المُسَمَّى: «بَعلًا».\ndeeds\nابتسم في وجه أخيك، أو ساعد جارك في حمل متاعه، أو ألقِ كلمة طيبة على زملائك، فكل هذا من الإحسان.\nقل: \"اللهم اهدني الصراط المستقيم\".\nوزع شريطًا أو كتيبًا على زملائك أو في الحي تدعوهم به إلى الله.\nguid\nالنسب والجاه لا ينجيان العبد، والمعول عليه صالح العمل بعد رحمة أرحم الراحمين.\nاعلم أن الفرج يأتي بعد الشدة والضيق، فلا تيأس، وأن من ترك شيئًا لله عوضه الله خيرًا منه.\nدعاء غير الله مناف للتقوى، فاحرص على تحقيق التقوى بدعاء الله وحده سبحانه.\nrefl\nفَلَمَّآ أَسۡلَمَا وَتَلَّهُۥ لِلۡجَبِينِ ١٠٣\nانقادا وخضعا لأمر الله تعالى؛ قال ابن عباس: \"أضجعه على جبينه على الأرض والجبهة بين الجبينين\". البغوي:٣/٦٦٧.\nما فائدة التعبير بصيغة المثنى في قوله: (أسلما)؟\nقَدۡ صَدَّقۡتَ ٱلرُّءۡيَآۚ\nأي: قد حصل المقصود من رؤياك وإضجاعك ولدك للذبح. ابن كثير:٤/١٧.\nكيف صَدَّق الرؤيا وهو لم يذبح ولده؟\nإِنَّ هَٰذَا لَهُوَ ٱلۡبَلَٰٓؤُاْ ٱلۡمُبِينُ ١٠٦\nهو خليل الرحمن، والخلة أعلى أنواع المحبة، وهو منصب لا يقبل المشاركة، ويقتضي أن تكون جميع أجزاء القلب متعلقة بالمحبوب؛ فلما تعلقت شعبة من شعب قلبه بابنه إسماعيل أراد تعالى أن يصفي وُدَّه، ويختبر خلته، فأمره أن يذبح مَن زاحم حبُّه حب ربه؛ فلما قدم حب الله، وآثره على هواه، وعزم على ذبحه، وزال ما في القلب من المزاحم، بقي الذبح لا فائدة فيه. السعدي:٧٠٦.\nكانت هذه الواقعة امتحانًا وتصفية لقلب إبراهيم -عليه السلام- بيِّن ذلك.\nوَفَدَيۡنَٰهُ بِذِبۡحٍ عَظِيمٖ ١٠٧\nكان عظيمًا من جهة أنه كان فداءً لإسماعيل، ومن جهة أنه من جملة العبادات الجليلة، ومن جهة أنه كان قربانًا وسُنَّة إلى يوم القيامة. السعدي:٧٠٦.\nما وجه وصف القربان بأنه عظيم؟\nوَتَرَكۡنَا عَلَيۡهِ فِي ٱلۡأٓخِرِينَ ١٠٨ سَلَٰمٌ عَلَىٰٓ إِبۡرَٰهِيمَ ١٠٩\nسأل إبراهيم، فقال: ﴿وَٱجۡعَل لِّي لِسَانَ صِدۡقٖ فِي ٱلۡأٓخِرِينَ﴾ [الشعراء: ٨٤] قال: فترك الله عليه الثناء الحسن في الآخرين، كما ترك اللسان السوء على فرعون وأشباهه. الطبري:٢١/٩١.\nاذكر علامة على إرادة الله سبحانه الخير بالإنسان تظهر بعد موته.\nوَبَٰرَكۡنَا عَلَيۡهِ وَعَلَىٰٓ إِسۡحَٰقَۚ وَمِن ذُرِّيَّتِهِمَا مُحۡسِنٞ وَظَالِمٞ لِّنَفۡسِهِۦ مُبِينٞ ١١٣\nوفيه تنبيه على أن الخبيث والطيّب لا يجري أمرهما على العِرق والعنصر؛ فقد يلد البَرُّ الفاجرَ والفاجر البَّر، وعلى أن فساد الأعقاب لا يُعدّ غضاضة على الآباء، وأن مناط الفضل هو خصال الذات وما اكتسب المرء من الصالحات؛ وأمَّا كرامة الآباء فتكملة للكمال، وباعث على الاتّسام بفضائل الخِلال. ابن عاشور:٢٣/ ١٦٢.\nالخبيث والطيب لا يجري أمرهما على العِرق، بين ذلك من الآية الكريمة.\nوَبَٰرَكۡنَا عَلَيۡهِ وَعَلَىٰٓ إِسۡحَٰقَۚ وَمِن ذُرِّيَّتِهِمَا مُحۡسِنٞ وَظَالِمٞ لِّنَفۡسِهِۦ مُبِينٞ ١١٣\nلما ذكر البركة في الذرية والكثرة قال: منهم محسن، ومنهم مسيء، وأن المسيء لا تنفعه بنوة النبوة؛ فاليهود والنصارى وإن كانوا من ولد إسحاق، والعرب وإن كانوا من ولد إسماعيل، فلا بد من الفرق بين المحسن والمسيء والمؤمن والكافر. القرطبي:١٨/٨٣.\nهل يكفي عنك صلاح أبيك؟ وهل يضرك فساده؟"],[451,"§الصافات\nwords\nالغَابِرِينَالبَاقِينَ فِي العَذَابِ.\nأَبَقَهَرَبَ مِن بَلَدِهِ مِن غَيرِ إِذنِ رَبِّهِ.\nفَسَاهَمَاقتَرَعَ رُكَّابُ السَّفِينَةِ؛ لِتَخفِيفِ الحُمُولَةِ خَوفَ الغَرَقِ.\nالمُدحَضِينَالمَغلُوبِينَ بِالقُرعَةِ.\nفَالتَقَمَهُابتَلَعَهُ.\nمُلِيمٌآتٍ بِمَا يُلاَمُ عَلَيهِ.\nفَنَبَذنَاهُفَطَرَحنَاهُ مِن بَطنِ الحُوتِ.\ndeeds\nقل: \"اللهم اجعلني من عبادك المخلَصين\".\nتذكر أحدًا من معارفك دعوته حتى يئست من هدايته، ثم استغفر الله من يأسك؛ فإنه معصية لله سبحانه.\nسبح الله تعالى لعل الله يدفع عنك البلاء بذلك.\nguid\nتأمل في الوعيد الشديد لكل من كذب الرسل وآذاهم.\nاعلم أن العقل السوي يقود العبد المؤمن للاعتبار والتفكر في سنن الله تعالى.\nاعلم أن أعظم الإفك ما كان متعلقًا بحق الله تعالى.\nrefl\nسَلَٰمٌ عَلَىٰٓ إِلۡ يَاسِينَ ١٣٠ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ١٣١ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ ١٣٢\nوفي قصة إلياس إنباء بأن الرسول عليه أداء الرسالة، ولا يلزم من ذلك أن يشاهد عقاب المكذِّبين ولا هلاكَهم للرد على المشركين الذين قالوا: ﴿مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ﴾؛ قال تعالى: ﴿قُل رَّبِّ إِمَّا تُرِيَنِّي مَا يُوعَدُونَ * رَبِّ فَلَا تَجۡعَلۡنِي فِي ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ * وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمۡ لَقَٰدِرُونَ﴾ [المؤمنون: ٩٣ - ٩٥]. ابن عاشور:٢٣/١٧٠.\nعلى الداعية تبليغ الدعوة لا غير، وليس عليه انتظار عقوبة من خالفه، بيِّن ذلك من الآية الكريمة.\nوَإِنَّكُمۡ لَتَمُرُّونَ عَلَيۡهِم مُّصۡبِحِينَ ١٣٧ وَبِٱلَّيۡلِۚ أَفَلَا تَعۡقِلُونَ ١٣٨\nتمرون بالنهار والليل عليهم؛ إذا ذهبتم إلى أسفاركم ورجعتم، ﴿أَفَلَا تَعۡقِلُونَ﴾ فتعتبرون بهم. البغوي:٣/٦٧٨.\nبقاء آثار السابقين للاعتبار والتخويف وليس للتسلية والترفيه، بين هذا من خلال الآية.\nوَإِنَّ يُونُسَ لَمِنَ ٱلۡمُرۡسَلِينَ ١٣٩ إِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ١٤٠ فَسَاهَمَ فَكَانَ مِنَ ٱلۡمُدۡحَضِينَ ١٤١ فَٱلۡتَقَمَهُ ٱلۡحُوتُ وَهُوَ مُلِيمٞ ١٤٢ فَلَوۡلَآ أَنَّهُۥ كَانَ مِنَ ٱلۡمُسَبِّحِينَ ١٤٣ لَلَبِثَ فِي بَطۡنِهِۦٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ ١٤٤\nواعلم أن الغرض من ذكر يونس هنا تسلية النبي -صلى الله عليه وسلم- فيما يلقاه من ثقل الرسالة بأن ذلك قد أثقل الرسل من قبله؛ فظهرت مرتبة النبي -صلى الله عليه وسلم-في صبره على ذلك، وعدم تذمّره، ولإِعلام جميع الناس بأنه مأمور من الله تعالى بمداومة الدعوة للدين؛ لأن المشركين كانوا يلومونه على إلحاحِه عليهم، ودعوته إياهم في مختلف الأزمان والأحوال. ابن عاشور:٢٣/١٧٨.\nما الغرض من ذكر قصة يونس -عليه السلام-؟\nوَإِنَّ يُونُسَ لَمِنَ ٱلۡمُرۡسَلِينَ ١٣٩ إِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ١٤٠\nولم يذكر الله ما غاضب عليه، ولا ذنبه الذي ارتكبه؛ لعدم فائدتنا بذكره، وإنَّما فائدتنا بما ذُكّرنا عنه أنه أذنب، وعاقبه الله مع كونه من الرسل الكرام، وأنه نجاه بعد ذلك، وأزال عنه الملام، وقيَّض له ما هو سبب صلاحه. السعدي:٧٠٧.\nماذا تستفيد من علمك أن نبيًا من الأنبياء عوقب بسبب ذنب فعله؟\nإِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ١٤٠\nأي: أراد الهروب، ودخل في البحر، وعبر عن هروبه بالإباق من حيث هو عبد الله، فر عن غير إذن مولاه؛ فهذه حقيقة الإباق. ابن عطية: ٤/٤٨٥.\nالإباق لفظ يستخدم لهروب العبد من سيده، فكيف قيل عن يونس أنه أبق مع أنه حر؟\nإِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ١٤٠\nأي: هرب إلى السفينة. و(الفلك) هنا واحد، و(المشحون): المملوء. وسبب هروبه غضبه على قومه حين لم يؤمنوا. ابن جزي:٢/٢٤١.\nلم هرب نبي الله يونس -عليه السلام- إلى الفلك المشحون؟\nفَلَوۡلَآ أَنَّهُۥ كَانَ مِنَ ٱلۡمُسَبِّحِينَ ١٤٣\nأخبر الله- عز وجل- أن يونس كان من المسبحين، وأن تسبيحه كان سبب نجاته، ولذلك قيل: إن العمل الصالح يرفع صاحبه إذا عثر. قال الحسن: \"ما كان له صلاة في بطن الحوت، ولكنه قدم عملًا صالحًا في حال الرخاء؛ فذكره الله به في حال البلاء\". القرطبي:١٨/٩٩.\nما سبب نجاة نبي الله يونس -عليه السلام-؟"],[452,"§الصافات\nwords\nمَا لَكُم كَيفَ تَحكُمُونَبِئسَ الحُكمُ مَا تَحكُمُونَهُ.\nسُلطَانٌحُجَّةٌ.\nلَمُحضَرُونَإِنَّ الكُفَّارَ سَيُحضَرُونَ لِلعَذَابِ يَومَ القِيَامَةِ.\nبِفَاتِنِينَبِمُضِلِّينَ أَحَدًا.\nصَالِ الجَحِيمِمَن يَصلَى الجَحِيمَ بِدُخُولِهَا وَمُقَاسَاةِ حَرِّهَا.\nالصَّآفُّونَالوَاقِفُونَ صُفُوفًا فِي عِبَادَةِ اللهِ.\nبِسَاحَتِهِمبِفِنَائِهِم.\ndeeds\nقل: \"سبحان الله وبحمده؛ عدد خلقه، ورضا نفسه، وزنة عرشه، ومداد كلماته\".\nانضبط في الصف مستويًا عند أدائك الصلاة.\nانصر هذه الأمة برسالة ترسلها لتكون من عباد الله الناصرين لدينه.\nguid\nاعتقد جازمًا أن دين الله تعالى منصور لا محالة.\nأمرنا الله تعالى بالإعراض عن المكذبين.\nنزه الله وسبحه إذا سمعت قـول الأفاكين.\nrefl\nوَجَعَلُواْ بَيۡنَهُۥ وَبَيۡنَ ٱلۡجِنَّةِ نَسَبٗاۚ وَلَقَدۡ عَلِمَتِ ٱلۡجِنَّةُ إِنَّهُمۡ لَمُحۡضَرُونَ ١٥٨\nأي: جعل هؤلاء المشركون بالله بين الله وبين الجنة نسبًا... والحال أن الجِنَّةَ قد علمت أنهم محضرون بين يدي الله؛ ليجازيهم عبادًا أذلاء، فلو كان بينهم وبينه نسب لم يكونوا كذلك. السعدي:٧٠٨.\nما المقصد من وراء الإخبار عن الجِنَّة بأنهم محضرون للحساب؟\nفَإِنَّكُمۡ وَمَا تَعۡبُدُونَ ١٦١ مَآ أَنتُمۡ عَلَيۡهِ بِفَٰتِنِينَ ١٦٢ إِلَّا مَنۡ هُوَ صَالِ ٱلۡجَحِيمِ ١٦٣\nوفيها من المعاني أن الشياطين لا يصلون إلى إضلال أحد إلا من كتب الله عليه أنه لا يهتدي، ولو علم الله -جل وعز- أنه يهتدي لحال بينه وبينهم. القرطبي:١٨/١١٢.\nهل يمكن للشيطان أن يصل لإضلالك متى شاء؟ وماذا تستفيد من ذلك؟\nوَمَا مِنَّآ إِلَّا لَهُۥ مَقَامٞ مَّعۡلُومٞ ١٦٤\nأي: ما منا ملك إلا له مقام معلوم في السموات؛ يعبد الله فيه، قال ابن عباس: \"ما في السموات موضع شبر إلا وعليه ملك يصلي أو يسبح\". البغوي:٣/٦٨١.\nبيّن حال الملائكة في العبادة.\nوَإِنَّا لَنَحۡنُ ٱلصَّآفُّونَ ١٦٥\nأي: الواقفون في العبادة صفوفًا؛ ولذلك أمر المسلمون بتسوية الصفوف في صلاتهم؛ ليقتدوا بالملائكة، وليس أحد من أهل الملل يصلون صفوفًا إلا المسلمون. ابن جزي:٢/٢٤٤.\nالملائكة أعظم المخلوقات قوة، وأشدها لله ذلَّة؛ بين هذا من خلال الآية.\nوَإِنَّا لَنَحۡنُ ٱلصَّآفُّونَ ١٦٥ وَإِنَّا لَنَحۡنُ ٱلۡمُسَبِّحُونَ ١٦٦\nعن أبي نضرة قال: كان عمر إذا أقيمت الصلاة أقبل على الناس بوجهه، فقال: \"يا أيها الناس استووا، إن الله إنَّما يريد بكم هدي الملائكة ﴿وَإِنَّا لَنَحۡنُ ٱلصَّآفُّونَ وَإِنَّا لَنَحۡنُ ٱلۡمُسَبِّحُونَ﴾\" استووا، تقدم أنت يا فلان، تأخر أنت أي هذا، فإذا استووا تقدم فكبر. الطبري:٢١/١٢٨.\nتَشَبَّهَ المؤمنون بالملائكة في أمرٍ فيه تعظيم لله -عز وجل-، وضح ذلك.\nسُبۡحَٰنَ رَبِّكَ رَبِّ ٱلۡعِزَّةِ عَمَّا يَصِفُونَ ١٨٠\nلما ذكر في هذه السورة كثيرًا من أقوالهم الشنيعة التي وصفوه بها نزه نفسه عنها فقال: ﴿سُبۡحَٰنَ رَبِّكَ﴾. السعدي:٧٠٩.\nلماذا ختم السورة بتسبيح نفسه سبحانه؟\nوَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ١٨٢\n﴿وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ﴾: يقول تعالى ذكره: والحمد لله رب الثقلين: الجن والإنس، خالصًا دون ما سواه؛ لأن كل نعمة لعباده فمنه، فالحمد له خالص لا شريك له، كما لا شريك له في نعمه عندهم. الطبري:٢١/١٣٤.\nلماذا يجب تخصيص الله -جل وعلا- بالحمد على النعم؟"],[453,"§صٓ\nwords\nالمِلَّةِ الآخِرَةِدِينِ آبَائِنَا وَدِينِ النَّصَارَى.\nاختلاقكذب وافتراء\nفَليَرتَقُوا فِي الأَسبَابِفَليَأخُذُوا بِالأَسبَابِ المُوصِلَةِ إِلَى السَّمَاءِ، وَليَمنَعُوا الوَحيَ.\nوَأَصحَابُ الأَيكَةِأَصحَابُ الأَشجَارِ وَالبَسَاتِينِ؛ وَهُم قَومُ شُعَيبٍ -عليه السلام-.\nفَوَاقٍرُجُوعٍ.\nقِطَّنَانَصِيبَنَا مِنَ العَذَابِ.\ndeeds\nقل: \"لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير\".\nقل: \"اللهم اهزم الكفرة الذين يصدون عن سبيلك، ويعادون أهل دينك\".\nاقرأ اليوم كتابًا في التفسير فيه شرح لدرسك الذي تحفظه من القرآن.\nguid\nاعتبر بالقرون الماضية التي أهلكها الله تعالى.\nمن سنن الله الباقية إلى قيام الساعة سب دعاة الحق والاستهزاء بهم، فلا يُضِرْكَ ذلك.\nلا تكن حاسدًا للناس على نعم الله تعالى، فأنت بذلك تعترض على قضاء الله وقدره.\nrefl\nوَٱلۡقُرۡءَانِ ذِي ٱلذِّكۡرِ ١ بَلِ ٱلَّذِينَ كَفَرُواْ فِي عِزَّةٖ وَشِقَاقٖ ٢\nأي: إن في هذا القرآن لذكرًا لمن يتذكر، وعبرة لمن يعتبر، وإنَّما لم ينتفع به الكافرون لأنهم ﴿فِي عِزَّةٍ﴾ أي: استكبار عنه وحمية. (وشقاق) أي: ومخالفة له، ومعاندة، ومفارقة. ابن كثير:٤/٢٧.\nاذكر الموانع التي تمنع الإفادة من القرآن في الآية.\nبَلِ ٱلَّذِينَ كَفَرُواْ فِي عِزَّةٖ وَشِقَاقٖ ٢\nقال بعض أهل العلم: أصل الشقاق من المشقة؛ لأن المخالف المعاند يجتهد في إيصال المشقة إلى من هو مخالف معاند. وقال بعضهم: أصل الشقاق من شق العصا؛ وهو الخلاف والتفرق. الشنقيطي:٦/٣٣٠.\nما وجه وصف الله تعالى الكفار بأنهم في شقاق؟\nوَعَجِبُوٓاْ أَن جَآءَهُم مُّنذِرٞ مِّنۡهُمۡۖ وَقَالَ ٱلۡكَٰفِرُونَ هَٰذَا سَٰحِرٞ كَذَّابٌ ٤\nولفظ: (هذا) أشاروا به إلى النبي -صلى الله عليه وسلم- استعملوا اسم الإِشارة لتحقير مثله. ابن عاشور:٢٣/٢٠٩.\nلماذا استعمل المشركون اسم الإشارة في التعبير عن النبي -صلى الله عليه وسلم-؟\nوَٱنطَلَقَ ٱلۡمَلَأُ مِنۡهُمۡ أَنِ ٱمۡشُواْ وَٱصۡبِرُواْ عَلَىٰٓ ءَالِهَتِكُمۡۖ إِنَّ هَٰذَا لَشَيۡءٞ يُرَادُ ٦\n﴿لَشَيۡءٌ يُرَادُ﴾ أي: يُقصد؛ أي: له قصد ونية غير صالحة في ذلك، وهذه شبهة لا تروج إلا على السفهاء؛ فإن من دعا إلى قول حق أو غير حق لا يُرَدُّ قوله بالقدح في نيته، فنيته وعمله له، وإنَّما يُرَدُّ بمقابلته بما يبطله ويفسده من الحجج والبراهين. السعدي:٧١٠.\nوضح من خلال هذه الآية: كيف ترد على من يقدح في نية العلماء والدعاة.\nأَءُنزِلَ عَلَيۡهِ ٱلذِّكۡرُ مِنۢ بَيۡنِنَاۚ بَلۡ هُمۡ فِي شَكّٖ مِّن ذِكۡرِيۚ بَل لَّمَّا يَذُوقُواْ عَذَابِ ٨\nإنَّما اغتروا بطول الإمهال، ولو ذاقوا عذابي على الشرك لزال عنهم الشك. القرطبي:١٨/١٣٥-١٣٦.\nما سبب اغترار الكفار وإصرارهم على الشرك؟\nجُندٞ مَّا هُنَالِكَ مَهۡزُومٞ مِّنَ ٱلۡأَحۡزَابِ ١١\nهذا وعيد بهزيمتهم في القتال، وقد هزموا يوم بدر وغيره. ابن جزي:٢/ ٢٤٨.\nوعد الله نبيه بهزيمة المشركين في بداية دعوته في مكة والمسلمون مستضعفون، فمتى تحقق هذا الوعد؟\nكَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَعَادٞ وَفِرۡعَوۡنُ ذُو ٱلۡأَوۡتَادِ ١٢\nووُصف فرعون بـــــــ﴿ذُو ٱلۡأَوۡتَادِ﴾ لعظمة ملكه وقوته؛ فلم يكن ذلك ليحول بينه وبين عذاب الله. ابن عاشور:٢٣/٢٢٠.\nما فائدة وصف فرعون بــــــ ﴿ذُو ٱلۡأَوۡتَادِ﴾؟"],[454,"§صٓ\nwords\nذَا الأَيدِصَاحِبَ القُوَّةِ عَلَى الطَّاعَةِ، وَفِي الحَربِ.\nأَوَّابٌكَثِيرُ الرُّجُوعِ إِلَى مَا يُرضِي اللهَ.\nوَلاَ تُشطِطلاَ تَجُر فِي حُكمِكَ، وَلاَ تَظلِم.\nأَكفِلنِيهَاأَعطِنِيهَا، وَانزِل لِي عَنهَا.\nالخُلَطَاءِالشُّرَكَاءِ.\nلَزُلفَىلَقُربَى وَمَكَانَةً.\nمَآبٍمَرجِعٍ.\ndeeds\nاتخذ لنفسك وردًا من التسبيح وغيره من الأذكار في الصباح والمساء.\nقل: \"اللهم إني أعوذ بك أن أضِل أو أُضَل، أو أزِل أو أُزَل، أو أَظلِم أو أُظلَم، أو أَجهَل أو يُجهَل علي\".\nاستغفر الله مائة مرة؛ واسأل الله أن يقبل استغفارك.\nguid\nكن دائم التذكر والتحدث عن قصص الأنبياء والصالحين.\nاصبر على أذى من آذاك.\nاحذر اتباع الهوى؛ فهو سبب الضلال والإضلال، والزم العدل والحق في حكمك.\nrefl\nٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱذۡكُرۡ عَبۡدَنَا دَاوُۥدَ ذَا ٱلۡأَيۡدِۖ إِنَّهُۥٓ أَوَّابٌ ١٧\nذكر داود ومن بعده من الأنبياء في هذه السورة فيه تسلية للنبي- صلى لله عليه وسلم-، ووعد له بالنصر، وتفريج الكرب، وإعانة له على ما أمر به من الصبر؛ وذلك أن الله ذكر ما أنعم به على داود من تسخير الطير والجبال، وشدّة ملكه، وإعطائه الحكمة، وفصل الخطاب، ثم الخاتمة له في الآخرة بالزلفى وحسن المآب؛ فكأنه يقول: يا محمد كما أنعمنا على داود بهذه النعم كذلك ننعم عليك، فاصبر ولا تحزن على ما يقولون. ابن جزي:٢/٢٤٩.\nما المناسبة بين أمر الله لسيدنا محمد -صلى الله عليه وسلم- بالصبر، وأمره له بذكر داود؟\nٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱذۡكُرۡ عَبۡدَنَا دَاوُۥدَ ذَا ٱلۡأَيۡدِۖ\nمن الفوائد والحكم في قصة داود... أن الله تعالى يمدح ويحب القوة في طاعته؛ قوة القلب والبدن؛ فإنه يحصل منها من آثار الطاعة وحسنها وكثرتها ما لا يحصل مع الوهن وعدم القوة، وأن العبد ينبغي له تعاطي أسبابها، وعدم الركون إلى الكسل والبطالة المخلقة بالقوى المضعفة للنفس. السعدي:٧١٣.\nإن الله تعالى يحب القوة في طاعته، بين ذلك من خلال وصفه تعالى لداود -عليه السلام- بأنه ﴿ذَا ٱلۡأَيۡدِۖ﴾ أي: ذا القوة.\nوَءَاتَيۡنَٰهُ ٱلۡحِكۡمَةَ وَفَصۡلَ ٱلۡخِطَابِ ٢٠\nمن الفوائد والحكم في قصة داود... أن من أكبر نِعَم الله على عبده أن يرزقه العلم النافع، ويعرف الحكم والفصل بين الناس، كما امتن الله به على عبده داود -عليه السلام-. السعدي:٧١٣.\nماذا تستفيد من امتنان الله على داود بإتيانه الحكمة؟\nإِنَّ هَٰذَآ أَخِي لَهُۥ تِسۡعٞ وَتِسۡعُونَ نَعۡجَةٗ وَلِيَ نَعۡجَةٞ وَٰحِدَةٞ فَقَالَ أَكۡفِلۡنِيهَا وَعَزَّنِي فِي ٱلۡخِطَابِ ٢٣ قَالَ لَقَدۡ ظَلَمَكَ بِسُؤَالِ نَعۡجَتِكَ إِلَىٰ نِعَاجِهِۦۖ وَإِنَّ كَثِيرٗا مِّنَ ٱلۡخُلَطَآءِ لَيَبۡغِي بَعۡضُهُمۡ عَلَىٰ بَعۡضٍ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَقَلِيلٞ مَّا هُمۡۗ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَٱسۡتَغۡفَرَ رَبَّهُۥ وَخَرَّۤ رَاكِعٗاۤ وَأَنَابَ۩ ٢٤\nوفي كتب بني إسرائيل في هذه القصة صور لا تليق، وقد حدَّث بها قصاصٌ في صدر هذه الأمة؛ فقال علي بن أبي طالب -رضي الله عنه-: \"من حدث بما قال هؤلاء القصاص في أمر داود -عليه السلام- جلدته حدين لما ارتكب من حرمة من رفع الله محله\". ابن عطية:٤/٤٩٩.\nفيما نقل عن علي بن أبي طالب -رضي الله عنه- في هذه القصة حفظ لمقام النبوة؛ وضح ذلك.\nوَإِنَّ كَثِيرٗا مِّنَ ٱلۡخُلَطَآءِ لَيَبۡغِي بَعۡضُهُمۡ عَلَىٰ بَعۡضٍ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَقَلِيلٞ مَّا هُمۡۗ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَٱسۡتَغۡفَرَ رَبَّهُۥ وَخَرَّۤ رَاكِعٗاۤ وَأَنَابَ۩ ٢٤\n﴿إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ﴾؛ فإنهم لا يظلمون أحدًا، ﴿وَقَلِيلٌ مَّا هُمۡۗ﴾ يعني: الصالحين. القرطبي:١٨/١٧٢.\nحثت الآية على أهمية مراعاة الإيمان والصلاح في اختيار الشريك؛ وضّح ذلك.\nوَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَٱسۡتَغۡفَرَ رَبَّهُۥ وَخَرَّۤ رَاكِعٗاۤ وَأَنَابَ۩ ٢٤ فَغَفَرۡنَا لَهُۥ ذَٰلِكَۖ\nالاستغفار والعبادة -خصوصًا الصلاة- من مكفرات الذنوب؛ فإن الله رتب مغفرة ذنب داود على استغفاره وسجوده. السعدي:٧١٣.\nمن خلال الآية: ما أهمية الصلاة في تكفير الذنوب؟\nيَٰدَاوُۥدُ إِنَّا جَعَلۡنَٰكَ خَلِيفَةٗ فِي ٱلۡأَرۡضِ فَٱحۡكُم بَيۡنَ ٱلنَّاسِ بِٱلۡحَقِّ وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِۚ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمۡ عَذَابٞ شَدِيدُۢ بِمَا نَسُواْ يَوۡمَ ٱلۡحِسَابِ ٢٦\nومعظم الكمالات صعبة على النفس؛ لأنها ترجع إلى تهذيب النفس، والارتقاء بها عن حضيض الحيوانية، فالاسترسال في اتباعها وقوع في الرذائل في الغالب. ابن عاشور:٢٣/٢٤٤.\nاتباع الهوى ينافي إدراك الكمالات، بين هذا المعنى من الآية الكريمة."],[455,"§صٓ\nwords\nالصَّافِنَاتُالخُيُولُ الوَاقِفَةُ عَلَى ثَلاَثِ قَوَائِمَ، وَتَرفَعُ الرَّابِعَةَ؛ لِنَجَابَتِهَا وَخِفَّتِهَا.\nالجِيَادُالخُيُولُ الأَصِيلَةُ السَّرِيعَةُ.\nفَطَفِقَشَرَعَ.\nمَسحًا بِالسُّوقِ وَالأَعنَاقِيَمسَحُ سِيقَانَهَا وَأَعنَاقَهَا، أَو يَقطَعُهَا بِالسَّيفِ تَقَرُّبًا إِلَى اللهِ.\nرُخَاءًلَيِّنَةً طَيِّعَةً.\nبِنُصبٍمَشَقَّةٍ، وَتَعَبٍ.\ndeeds\nاقرأ سورة من جزء عم، واقرأ معناها، ثم تدبر ما فيها من الفوائد والعلم والعمل.\nانظر شيئًا تملكه، ويشغلك كثيرًا عن طاعة الله، وتصدق به في سبيل الله؛ لعل الله يعوضك خيرًا منه.\nسَلِ الله تعالى من خيري الدنيا والآخرة اقتداءً بأنبيائه.\nguid\nاعلم أن أصحاب العقول السليمة هم أهل الانتفاع والتذكر بالمواعظ.\nاحذر أن تنشغل بشيء من الدنيا عن طاعة الله تعالى.\nإذا أذنبت، أو أصابك بلاء، أو هم؛ فكن أوابًا رجاعًا إلى الله تعالى.\nrefl\nكِتَٰبٌ أَنزَلۡنَٰهُ إِلَيۡكَ مُبَٰرَكٞ لِّيَدَّبَّرُوٓاْ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُوْلُواْ ٱلۡأَلۡبَٰبِ ٢٩\nوظاهر هذه الآية يعطي أن التدبر من أسباب إنزال القرآن، فالترتيل إذًا أفضل من الهذِّ؛ إذ التدبر لا يكون إلا مع الترتيل. ابن عطية:٤/٥٠٣.\nوضح العلاقة بين التدبر والترتيل.\nكِتَٰبٌ أَنزَلۡنَٰهُ إِلَيۡكَ مُبَٰرَكٞ لِّيَدَّبَّرُوٓاْ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُوْلُواْ ٱلۡأَلۡبَٰبِ ٢٩\nوكل آيات القرآن مبارك فيها؛ لأنها: إمّا مرشدة إلى خير، وَإمّا صارفة عن شرّ وفساد، وذلك سبب الخير في العاجل والآجل، ولا بركة أعظم من ذلك. ابن عاشور:٢٣/٢٥١.\nكل كتاب الله تعالى مبارك فيه، بين ذلك من الآية الكريمة.\nكِتَٰبٌ أَنزَلۡنَٰهُ إِلَيۡكَ مُبَٰرَكٞ لِّيَدَّبَّرُوٓاْ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُوْلُواْ ٱلۡأَلۡبَٰبِ ٢٩\nو﴿أُوْلُواْ ٱلۡأَلۡبَٰبِ﴾: أهل العقول، وفيه تعريض بأن الذين لم يتذكروا بالقرآن ليسوا من أهل العقول، وأن التذكر من شأن المسلمين الذين يستمعون القول فيتّبعون أحسنه؛ فهم ممن تدبروا آياته فاستنبطوا من المعاني ما لم يعلموا... والكافرون أعرضوا عن التدبر؛ فلا جَرَمَ فاتهم التذكر. ابن عاشور:٢٣/٢٥٣.\nبيّن علامة أهل العقول من خلال الآية الكريمة.\nفَقَالَ إِنِّيٓ أَحۡبَبۡتُ حُبَّ ٱلۡخَيۡرِ عَن ذِكۡرِ رَبِّي حَتَّىٰ تَوَارَتۡ بِٱلۡحِجَابِ ٣٢\nوسميت الخيل خيرًا؛ لأنه معقود بنواصيها الخير: الأجر والمغنم. البغوي:٣/٧٠٣.\nلم سميت الخيل بالخير؟\nقَالَ رَبِّ ٱغۡفِرۡ لِي وَهَبۡ لِي مُلۡكٗا لَّا يَنۢبَغِي لِأَحَدٖ مِّنۢ بَعۡدِيٓۖ إِنَّكَ أَنتَ ٱلۡوَهَّابُ ٣٥\nقدم الاستغفار على طلب الملك؛ لأن أمور الدين كانت عندهم أهم من الدنيا، فقدّم الأولى والأهمّ. ابن جزي:٢/٢٥٥.\nلم قدّم سليمان -عليه السلام- الاستغفار على طلب الملك؟\nقَالَ رَبِّ ٱغۡفِرۡ لِي وَهَبۡ لِي مُلۡكٗا لَّا يَنۢبَغِي لِأَحَدٖ مِّنۢ بَعۡدِيٓۖ إِنَّكَ أَنتَ ٱلۡوَهَّابُ ٣٥ فَسَخَّرۡنَا لَهُ ٱلرِّيحَ تَجۡرِي بِأَمۡرِهِۦ رُخَآءً حَيۡثُ أَصَابَ ٣٦\nعن الحسن: أن نبي الله سليمان -عليه السلام- لمَّا عُرضت عليه الخيل، فشغله النظر إليها عن صلاة العصر ﴿حَتَّىٰ تَوَارَتۡ بِٱلۡحِجَابِ﴾؛ فغضب لله، فأمر بها فعقرت، فأبدله الله مكانها أسرع منها؛ سخر الريح تجري بأمره رخاء حيث شاء. الطبري:٢١/٢٠١-٢٠٢.\nبيّن من خلال الآية أن من ترك شيئًا لله عوضه الله خيرًا منه.\nوَٱذۡكُرۡ عَبۡدَنَآ أَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلشَّيۡطَٰنُ بِنُصۡبٖ وَعَذَابٍ ٤١\nوخص هذا الحال بالذكر من بين أحواله؛ لأنه مظهر توكّله على الله، واستجابة الله دعاءه بكشف الضر عنه. ابن عاشور: ٢٣/٢٦٨.\nلماذا خص حال مناداة أيوب -عليه السلام- ربه دون غيره من أحواله -عليه السلام-؟"],[456,"§صٓ\nwords\nضِغثًاحُزمَةَ شَمَارِيخَ أَو قَبضَةَ حَشِيشٍ.\nوَلاَ تَحنَثلاَ تَنقُض يَمِينَكَ الَّتِي حَلَفتَهَا بِضَربِ زَوجَتِكَ.\nأَخلَصنَاهُم بِخَالِصَةٍخَصَصنَاهُم بِخَصلَةٍ عَظِيمَةٍ.\nقَاصِرَاتُ الطَّرفِلاَ يَنظُرنَ إِلَى غَيرِ أَزوَاجِهِنَّ.\nأَترَابٌمُتَسَاوِيَاتُ السِّنِّ.\nنَفَادٍانقِطَاعٍ.\nلَشَرَّ مَآبٍأَسوَأَ مَرجِعٍ فِي الآخِرَةِ.\ndeeds\nتذكر قضية صبرت عليها واسأل الله أن يجعل صبرك عبادة لله في ميزان حسناتك.\nتذكر يمينًا أقسمته وحاول أن تبرَّ به تعظيمًا لأمر الله.\nاسأل الله أن لا يجعل الدنيا أكبر همك.\nguid\nقد يبتلي الله تعالى من يحبه من عباده؛ ليزيد في علو مقامه، ورفعة شأنه.\nالعـلاقـة التي تبنى على سخط الله تنقلـب في الآخرة إلى عـداواة.\nلا تكن سببًا في معصيةِ أحدٍ.\nrefl\nوَخُذۡ بِيَدِكَ ضِغۡثٗا فَٱضۡرِب بِّهِۦ وَلَا تَحۡنَثۡۗ إِنَّا وَجَدۡنَٰهُ صَابِرٗاۚ\nوذلك أن أيوب -عليه السلام- كان قد غضب على زوجته... وحلف إن شفاه الله تعالى ليضربنها مائة جلدة... فلما شفاه الله -عز وجل- وعافاه ما كان جزاؤها مع هذه الخدمة التامة والرحمة والشفقة والإحسان أن تُقابَل بالضرب؛ فأفتاه الله -عز وجل- أن يأخذ ضغثًا -وهو الشمراخ- فيه مائة قضيب، فيضربها به ضربة واحدة، وقد برت يمينه وخرج من حنثه، ووفى بنذره، وهذا من الفرج والمخرج لمن اتقى الله تعالى وأناب إليه. ابن كثير:٤/٤١.\nمن صدق في تقوى الله تعالى أوجد الله له مخرجًا، وضح هذا من الآية.\nوَٱذۡكُرۡ عِبَٰدَنَآ إِبۡرَٰهِيمَ وَإِسۡحَٰقَ وَيَعۡقُوبَ أُوْلِي ٱلۡأَيۡدِي وَٱلۡأَبۡصَٰرِ ٤٥\nالأيدي: جمع يد؛ وذلك عبارة عن قوتهم في الأعمال الصالحات، وإنَّما عبر عن ذلك بالأيدي؛ لأن الأعمال أكثر ما تُعمل بالأيدي. وأمَّا الأبصار؛ فعبارة عن قوة فهمهم، وكثرة علمهم؛ من قولك: أبصر الرجل إذا تبينت له الأمور. ابن جزي:٢/٢٥٧.\nفي وصف الله تعالى لأنبيائه ب﴿أُوْلِي ٱلۡأَيۡدِي وَٱلۡأَبۡصَٰرِ﴾ صفات مدح؛ وضّح هذه الصفات.\nهَٰذَا ذِكۡرٞۚ وَإِنَّ لِلۡمُتَّقِينَ لَحُسۡنَ مَـَٔابٖ ٤٩\n﴿هَٰذَا ذِكۡرُ﴾ بمعنى: هذا ذكر جميل في الدنيا، وشرف يذكرون به في الدنيا أبدًا. ﴿وَإِنَّ لِلۡمُتَّقِينَ لَحُسۡنَ مَـَٔابٍ﴾ أي: لهم مع هذا الذكر الجميل في الدنيا حسن المرجع في القيامة. القرطبي:١٨/٢٢٦.\nفي الآية ذكر لبعض جزاء المتقين في الدنيا والآخرة، وضح ذلك.\nمُّفَتَّحَةٗ لَّهُمُ ٱلۡأَبۡوَٰبُ ٥٠\nوهذا دليل أيضًا على الأمان التام، وأنه ليس في جنات عدن ما يوجب أن تغلق لأجله أبوابها. السعدي:٧١٥.\nفي الآية إشارة إلى نعمةٍ عظيمة ينعم الله بها على أهل الجنة، فما هي؟\n۞وَعِندَهُمۡ قَٰصِرَٰتُ ٱلطَّرۡفِ أَتۡرَابٌ ٥٢\n(وعندهم) من أزواجهم الحور العين (قاصرات) طرفهن على أزواجهن، وطرف أزواجهن عليهن؛ لجمالهم كلهم، ومحبة كل منهما للآخر، وعدم طموحه لغيره، وأنه لا يبغي بصاحبه بدلًا، ولا عنه عوضًا. السعدي:٧١٥.\nفي وصف الحور بأنهن ﴿قَٰصِرَٰتُ ٱلطَّرۡفِ﴾ إشارة إلى خلق ينبغي أن تتصف به المسلمة في الدنيا؛ لعله يكون سببًا في دخولها الجنة، فما هو؟\nإِنَّ هَٰذَا لَرِزۡقُنَا مَا لَهُۥ مِن نَّفَادٍ ٥٤\nوذلك أنهم كلما أخذوا ثمرة من ثمار شجرة من أشجارها، فأكلوها؛ عادت مكانها أخرى مثلها، فذلك لهم دائم أبدًا، لا ينقطع. الطبري:٢١/٢٢٣.\nبينت الآية فرقًا بين ثمار الجنة وثمار الدنيا، بين ذلك.\nقَالُواْ بَلۡ أَنتُمۡ لَا مَرۡحَبَۢا بِكُمۡۖ أَنتُمۡ قَدَّمۡتُمُوهُ لَنَاۖ فَبِئۡسَ ٱلۡقَرَارُ ٦٠\nأي: دعوتمونا إلى العصيان؛ (فبئس القرار لنا ولكم). (قَالُوا)؛ يعني الأتباع: (ربنا من قدم لنا هذا فزده عذابًا ضعفًا من النار). القرطبي:١٨/٢٣٣.\nما حال الأتباع من المتبوعين العصاة يوم القيامة؟ وماذا تفيد من ذلك؟"]])